insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('c2000000-0000-0000-0000-000000000001', 'ukmla', '25809d82-fe58-41d3-8ea8-70bf2b2b0e8c',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('c2000000-0000-0000-0000-000000000001', 'A', 'Continue ramipril and prescribe a course of oral antibiotics', false, 'Ruled out because there is no clinical or radiological evidence of infection (no fever, clear chest, normal CXR); antibiotics would not address an ACE inhibitor-induced cough.', 1),
('c2000000-0000-0000-0000-000000000001', 'B', 'Stop ramipril and switch to an angiotensin receptor blocker such as losartan', true, 'Correct. A dry cough is a well-recognised class effect of ACE inhibitors, caused by accumulation of bradykinin and substance P in the respiratory tract. It typically resolves within days to weeks of stopping the drug; switching to an ARB retains the antihypertensive and renoprotective benefit without this effect because ARBs do not inhibit bradykinin breakdown.', 2),
('c2000000-0000-0000-0000-000000000001', 'C', 'Continue ramipril and start a short-acting beta-agonist inhaler for presumed asthma', false, 'Ruled out because there is no wheeze or other evidence of airway obstruction, and new-onset asthma is far less likely than a recognised drug adverse effect starting soon after ACE inhibitor initiation.', 3),
('c2000000-0000-0000-0000-000000000001', 'D', 'Reduce the ramipril dose and reassess in 4 weeks', false, 'Ruled out because ACE inhibitor-induced cough is not reliably dose-dependent; the cough typically persists until the drug is stopped completely.', 4),
('c2000000-0000-0000-0000-000000000001', 'E', 'Reassure her that the cough is unrelated and continue ramipril unchanged', false, 'Ruled out because the temporal association with ACE inhibitor initiation strongly suggests a causal drug adverse effect that will not resolve without stopping the drug.', 5),
('c2000000-0000-0000-0000-000000000002', 'A', 'Halve the dose of atorvastatin and review in 6 weeks', false, 'Ruled out because continuing any dose of statin with a markedly elevated CK and ongoing symptoms risks progression to rhabdomyolysis and acute kidney injury; the drug must be stopped, not reduced.', 1),
('c2000000-0000-0000-0000-000000000002', 'B', 'Switch immediately to a different statin at an equivalent dose', false, 'Ruled out because switching to another statin while myopathy is active and CK is markedly raised risks worsening muscle injury; the statin class should be withheld until symptoms and CK resolve before any rechallenge is considered.', 2),
('c2000000-0000-0000-0000-000000000002', 'C', 'Continue atorvastatin and start a course of oral corticosteroids for presumed myositis', false, 'Ruled out because the clear temporal relationship with statin therapy and grossly elevated CK make drug-induced myopathy far more likely than autoimmune myositis; steroids are not indicated and continuing the statin would worsen the injury.', 3),
('c2000000-0000-0000-0000-000000000002', 'D', 'Reassure the patient that muscle aches are an expected side effect and continue treatment', false, 'Ruled out because a CK of 3200 U/L is markedly abnormal (not simple myalgia) and indicates significant muscle injury that requires stopping the drug, not reassurance.', 4),
('c2000000-0000-0000-0000-000000000002', 'E', 'Stop atorvastatin and ensure adequate hydration, with monitoring of renal function and CK', true, 'Correct. This presentation (symmetrical proximal myalgia with markedly raised CK) is consistent with statin-induced myopathy progressing towards rhabdomyolysis. The statin should be stopped immediately, the patient hydrated to protect renal function, and CK and renal function monitored until they normalise.', 5),
('c2000000-0000-0000-0000-000000000003', 'A', 'Concurrent use of ibuprofen and aspirin', true, 'Correct. Combining a non-selective NSAID with aspirin substantially increases the risk of peptic ulceration and upper GI bleeding, as both inhibit protective gastric prostaglandin synthesis via COX-1 inhibition, and the effects are additive; this risk is further increased by her age.', 1),
('c2000000-0000-0000-0000-000000000003', 'B', 'Her age alone, independent of medication use', false, 'Ruled out because although advanced age is a recognised risk factor for NSAID-related GI bleeding, it is the combination with NSAID/aspirin use that precipitates the bleed here, not age in isolation.', 2),
('c2000000-0000-0000-0000-000000000003', 'C', 'Her underlying diagnosis of osteoarthritis', false, 'Ruled out because osteoarthritis itself does not predispose to GI bleeding; the risk arises from the medications used to treat its symptoms.', 3),
('c2000000-0000-0000-0000-000000000003', 'D', 'Insufficient dietary fibre intake', false, 'Ruled out because dietary fibre intake is not a recognised major risk factor for upper GI bleeding in this context.', 4),
('c2000000-0000-0000-0000-000000000003', 'E', 'Use of paracetamol for background analgesia', false, 'Ruled out because paracetamol does not inhibit COX enzymes at analgesic doses and is not associated with peptic ulceration or GI bleeding.', 5),
('c2000000-0000-0000-0000-000000000004', 'A', $x$Graves' disease unrelated to his medication$x$, false, $x$Ruled out because although Graves' disease can cause thyrotoxicosis, the temporal association with long-term amiodarone use and its well-recognised effect on the thyroid make a drug-induced cause far more likely to be tested here.$x$, 1),
('c2000000-0000-0000-0000-000000000004', 'B', 'Subclinical hypothyroidism', false, 'Ruled out because the biochemistry (suppressed TSH with raised free T4) and clinical picture (weight loss, heat intolerance, palpitations) indicate thyrotoxicosis, not hypothyroidism.', 2),
('c2000000-0000-0000-0000-000000000004', 'C', 'Sick euthyroid syndrome due to his underlying heart disease', false, 'Ruled out because sick euthyroid syndrome typically shows low/normal TSH with low T3/T4 in the context of acute severe illness, not the clear thyrotoxic biochemical and clinical picture seen here.', 3),
('c2000000-0000-0000-0000-000000000004', 'D', 'Amiodarone-induced thyrotoxicosis', true, 'Correct. Amiodarone has a high iodine content and can cause either hypothyroidism or thyrotoxicosis; thyroid function should be monitored regularly during long-term treatment, and new thyrotoxic symptoms with a suppressed TSH and raised free T4 in a patient on amiodarone should prompt specialist endocrine referral and consideration of stopping the drug.', 4),
('c2000000-0000-0000-0000-000000000004', 'E', 'Normal expected effect of amiodarone requiring no further action', false, 'Ruled out because new thyrotoxic symptoms with abnormal thyroid function tests are not an expected benign finding and require further assessment and likely specialist input.', 5),
('c2000000-0000-0000-0000-000000000005', 'A', 'Stop the infusion and give oral chlorphenamine only', false, 'Ruled out because antihistamines do not reverse the life-threatening features of anaphylaxis (airway swelling, bronchospasm, hypotension); intramuscular adrenaline is required first-line.', 1),
('c2000000-0000-0000-0000-000000000005', 'B', 'Continue the infusion at a slower rate and monitor closely', false, 'Ruled out because continuing to administer the causative allergen during an anaphylactic reaction risks rapid clinical deterioration and death.', 2),
('c2000000-0000-0000-0000-000000000005', 'C', 'Stop the infusion immediately and give intramuscular adrenaline', true, 'Correct. This presentation (rapid-onset swelling, urticaria, wheeze, and hypotension after IV antibiotic administration) is anaphylaxis. The causative drug must be stopped immediately and intramuscular adrenaline given without delay, as it is the first-line treatment that reverses the life-threatening airway, breathing, and circulatory features.', 3),
('c2000000-0000-0000-0000-000000000005', 'D', 'Give intravenous adrenaline as the first-line route', false, 'Ruled out because intramuscular adrenaline (into the anterolateral thigh) is the recommended first-line route in anaphylaxis; IV adrenaline is reserved for specialist/critical care settings with cardiac monitoring due to the risk of dangerous arrhythmia.', 4),
('c2000000-0000-0000-0000-000000000005', 'E', 'Perform urgent skin prick allergy testing before giving any treatment', false, 'Ruled out because allergy testing has no role in the acute management of anaphylaxis and would dangerously delay life-saving treatment; it may be considered later, once the patient has recovered.', 5),
('c2000000-0000-0000-0000-000000000006', 'A', 'Continue methotrexate at a reduced dose and increase folic acid supplementation', false, 'Ruled out because continuing methotrexate in the presence of severe pancytopenia risks life-threatening infection and bleeding; the drug must be stopped, not merely reduced.', 1),
('c2000000-0000-0000-0000-000000000006', 'B', 'Reassure her that mouth ulcers are an expected side effect of methotrexate and continue current treatment', false, 'Ruled out because this is a severe adverse drug reaction with pancytopenia and clinical signs of possible sepsis, requiring urgent action, not reassurance.', 2),
('c2000000-0000-0000-0000-000000000006', 'C', 'Switch to subcutaneous methotrexate at the same dose to improve absorption', false, 'Ruled out because the problem is bone marrow toxicity from methotrexate itself, not poor oral absorption; changing the route would not address the underlying toxicity and could worsen it.', 3),
('c2000000-0000-0000-0000-000000000006', 'D', 'Stop methotrexate immediately and admit for urgent haematology/rheumatology input, with consideration of folinic acid rescue', true, $x$Correct. This is methotrexate-induced bone marrow suppression (pancytopenia) with signs of neutropenic sepsis risk (sore throat, mouth ulcers). Methotrexate must be stopped immediately, the patient admitted for urgent assessment, and folinic acid (calcium folinate) rescue considered to counteract methotrexate's antifolate toxicity, alongside neutropenic sepsis precautions.$x$, 4),
('c2000000-0000-0000-0000-000000000006', 'E', 'Arrange routine outpatient blood monitoring in one week', false, 'Ruled out because pancytopenia with signs of possible infection in a patient on methotrexate is a medical emergency requiring same-day admission, not deferred outpatient review.', 5),
('c2000000-0000-0000-0000-000000000007', 'A', 'Neuroleptic malignant syndrome', true, 'Correct. The combination of muscle rigidity, hyperthermia, autonomic instability (tachycardia), altered mental state, and markedly raised CK shortly after starting an antipsychotic is characteristic of neuroleptic malignant syndrome, a rare but life-threatening adverse reaction requiring immediate drug withdrawal and supportive/specialist management.', 1),
('c2000000-0000-0000-0000-000000000007', 'B', 'Serotonin syndrome', false, 'Ruled out because serotonin syndrome is typically caused by serotonergic drugs (e.g., SSRIs, MAOIs) rather than antipsychotics, and classically features clonus and hyperreflexia rather than the lead-pipe rigidity seen here; the clinical context (recent antipsychotic initiation) favours neuroleptic malignant syndrome.', 2),
('c2000000-0000-0000-0000-000000000007', 'C', 'Acute bacterial meningitis', false, 'Ruled out because although fever and confusion can occur, the marked muscle rigidity and grossly elevated CK, combined with recent antipsychotic initiation, point to a drug-induced cause rather than infection; meningitis would not typically cause this degree of CK elevation.', 3),
('c2000000-0000-0000-0000-000000000007', 'D', 'Malignant hyperthermia', false, 'Ruled out because malignant hyperthermia is triggered by volatile anaesthetic agents or suxamethonium during anaesthesia, not by antipsychotic medication started on a psychiatric ward.', 4),
('c2000000-0000-0000-0000-000000000007', 'E', 'Acute extrapyramidal dystonic reaction', false, 'Ruled out because a dystonic reaction causes sustained, often painful muscle spasms (e.g., torticollis, oculogyric crisis) without the fever, autonomic instability, and marked CK elevation seen in neuroleptic malignant syndrome.', 5),
('c2000000-0000-0000-0000-000000000008', 'A', 'Continue warfarin at the same dose and recheck INR in one week', false, 'Ruled out because an INR of 6.8 with active bleeding (gum bleeding, bruising) is a significant risk of serious haemorrhage and requires immediate action, not continuation of the same dose.', 1),
('c2000000-0000-0000-0000-000000000008', 'B', 'Give intravenous vitamin K and fresh frozen plasma immediately', false, 'Ruled out because this level of intervention (IV vitamin K plus FFP/prothrombin complex concentrate) is reserved for major, life-threatening bleeding; this patient has minor bleeding only, so oral vitamin K and withholding warfarin is the appropriate initial step.', 2),
('c2000000-0000-0000-0000-000000000008', 'C', 'Stop warfarin, withhold further doses, and give oral vitamin K, with INR rechecked', true, $x$Correct. Metronidazole inhibits hepatic CYP2C9, markedly increasing warfarin's anticoagulant effect. An INR of 6.8 with minor bleeding (no major/life-threatening bleeding) is managed by withholding warfarin and giving oral vitamin K to reduce the INR, with the INR rechecked to guide further management, per standard warfarin over-anticoagulation protocols.$x$, 3),
('c2000000-0000-0000-0000-000000000008', 'D', 'Increase the warfarin dose to compensate for the antibiotic interaction', false, 'Ruled out because the INR is already dangerously elevated due to the interaction; increasing the dose would worsen bleeding risk.', 4),
('c2000000-0000-0000-0000-000000000008', 'E', 'Switch immediately to a direct oral anticoagulant without any monitoring', false, $x$Ruled out because starting a new anticoagulant while the INR is markedly elevated and warfarin's effect is still present would risk over-anticoagulation and bleeding; the immediate priority is correcting the current over-anticoagulation.$x$, 5),
('c2000000-0000-0000-0000-000000000009', 'A', 'Start aspirin 75 mg daily for stroke prevention', false, 'Ruled out because aspirin monotherapy is not recommended for stroke prevention in atrial fibrillation; it is less effective than anticoagulation and does not adequately reduce stroke risk in this context.', 1),
('c2000000-0000-0000-0000-000000000009', 'B', 'Start a direct oral anticoagulant such as apixaban', true, 'Correct. Her CHA2DS2-VASc score of 4 indicates a significant stroke risk that outweighs bleeding risk, so anticoagulation is indicated. DOACs (e.g., apixaban, rivaroxaban) are recommended first-line over warfarin for non-valvular AF stroke prevention in most patients, given comparable or better efficacy, lower intracranial bleeding risk, and no need for routine INR monitoring.', 2),
('c2000000-0000-0000-0000-000000000009', 'C', 'No pharmacological prevention is needed as she is asymptomatic', false, 'Ruled out because stroke risk in atrial fibrillation depends on risk factors (reflected by CHA2DS2-VASc), not symptoms; a score of 4 clearly warrants anticoagulation regardless of symptom burden.', 3),
('c2000000-0000-0000-0000-000000000009', 'D', 'Start warfarin as first-line therapy in preference to a DOAC', false, 'Ruled out because current guidance favours DOACs over warfarin as first-line for most patients with non-valvular AF, reserving warfarin mainly for those with mechanical heart valves or where DOACs are contraindicated/unsuitable.', 4),
('c2000000-0000-0000-0000-000000000009', 'E', 'Start dual antiplatelet therapy with aspirin and clopidogrel', false, 'Ruled out because dual antiplatelet therapy is used for conditions like acute coronary syndrome/post-PCI, not as stroke prevention in atrial fibrillation, where anticoagulation is required instead.', 5),
('c2000000-0000-0000-0000-000000000010', 'A', 'Switch from unfractionated heparin to low molecular weight heparin at a lower dose', false, 'Ruled out because HIT antibodies cross-react with low molecular weight heparin; switching to LMWH would not resolve the problem and risks ongoing thrombosis.', 1),
('c2000000-0000-0000-0000-000000000010', 'B', 'Transfuse platelets to correct the thrombocytopenia before continuing heparin', false, 'Ruled out because platelet transfusion in HIT can potentiate thrombosis and is not indicated unless there is significant bleeding; the priority is stopping heparin and starting an alternative anticoagulant.', 2),
('c2000000-0000-0000-0000-000000000010', 'C', 'Stop heparin and do not restart any anticoagulation, since the patient is not bleeding', false, 'Ruled out because HIT is a prothrombotic state despite thrombocytopenia; stopping anticoagulation altogether would leave him at high risk of further venous or arterial thrombosis.', 3),
('c2000000-0000-0000-0000-000000000010', 'D', 'Continue the heparin infusion and monitor the platelet count daily', false, 'Ruled out because continuing heparin in suspected HIT risks life- and limb-threatening thrombosis (as demonstrated by the skin necrosis) and is contraindicated once HIT is suspected.', 4),
('c2000000-0000-0000-0000-000000000010', 'E', 'Stop all heparin products immediately and start an alternative non-heparin anticoagulant', true, 'Correct. This is heparin-induced thrombocytopenia (HIT), an immune-mediated prothrombotic disorder typically occurring 5-10 days after heparin exposure, presenting with a falling platelet count (often >50% drop) and paradoxically increased thrombotic risk (including skin necrosis at injection sites). All heparin (including LMWH and heparin-flushes) must be stopped immediately and replaced with a non-heparin anticoagulant such as a direct thrombin inhibitor or fondaparinux, because the patient remains at high thrombotic risk despite the low platelet count.', 5),
('c2000000-0000-0000-0000-000000000011', 'A', 'Give oral vitamin K only and observe', false, 'Ruled out because oral vitamin K acts too slowly to correct coagulopathy in life-threatening haemorrhage; IV vitamin K plus prothrombin complex concentrate is required for rapid reversal.', 1),
('c2000000-0000-0000-0000-000000000011', 'B', 'Withhold warfarin only, without giving any reversal agent, and monitor INR', false, 'Ruled out because simply withholding warfarin does not rapidly correct the coagulopathy in a patient with major active bleeding and haemodynamic instability; active reversal is required.', 2),
('c2000000-0000-0000-0000-000000000011', 'C', 'Stop warfarin and give intravenous vitamin K plus prothrombin complex concentrate', true, 'Correct. This is major, life-threatening bleeding on warfarin. Warfarin must be stopped and rapidly reversed with intravenous vitamin K (to restore ongoing synthesis of clotting factors) plus prothrombin complex concentrate (which immediately replaces factors II, VII, IX and X), alongside resuscitation; this is the fastest and most effective way to correct coagulopathy in major bleeding.', 3),
('c2000000-0000-0000-0000-000000000011', 'D', 'Transfuse fresh frozen plasma alone as the definitive reversal agent', false, 'Ruled out because prothrombin complex concentrate achieves faster, more complete factor replacement than FFP and is preferred for emergency warfarin reversal in major bleeding; FFP is a less effective alternative when PCC is unavailable.', 4),
('c2000000-0000-0000-0000-000000000011', 'E', 'Give protamine sulfate to reverse the anticoagulant effect', false, 'Ruled out because protamine sulfate reverses heparin, not warfarin; it has no role in warfarin reversal.', 5),
('c2000000-0000-0000-0000-000000000012', 'A', 'Stop both aspirin and ticagrelor 7 days before surgery as routine practice', false, 'Ruled out because stopping both antiplatelet agents this soon after a drug-eluting stent significantly raises the risk of stent thrombosis; elective surgery should instead be deferred.', 1),
('c2000000-0000-0000-0000-000000000012', 'B', 'Continue ticagrelor but stop aspirin only, without specialist input', false, 'Ruled out because decisions about interrupting any component of dual antiplatelet therapy this early after stenting should not be made without cardiology input, given the high risk of stent thrombosis.', 2),
('c2000000-0000-0000-0000-000000000012', 'C', 'Proceed with surgery as planned with no changes and no specialist discussion, since the hernia repair is low risk', false, 'Ruled out because although hernia repair itself carries a modest bleeding risk, the appropriate approach given the timing after stenting is to postpone elective surgery and seek cardiology advice rather than proceeding unchanged without discussion.', 3),
('c2000000-0000-0000-0000-000000000012', 'D', 'Switch ticagrelor to clopidogrel one week before surgery to reduce bleeding risk', false, 'Ruled out because switching antiplatelet agents does not remove the need for dual antiplatelet therapy in the early post-stent period, and this decision should not be made in isolation from cardiology and without addressing the fundamental issue of surgical timing.', 4),
('c2000000-0000-0000-0000-000000000012', 'E', 'Postpone elective surgery and continue dual antiplatelet therapy, seeking cardiology advice before any interruption', true, 'Correct. Premature discontinuation of dual antiplatelet therapy within the first 6-12 months after drug-eluting stent insertion carries a high risk of stent thrombosis, which can cause a fatal myocardial infarction. Elective, non-urgent surgery should be postponed where possible, and any decision to interrupt antiplatelet therapy should involve cardiology input to balance thrombotic and surgical bleeding risk.', 5),
('c2000000-0000-0000-0000-000000000013', 'A', 'Start low molecular weight heparin at the standard prophylactic dose as planned', false, 'Ruled out because starting an anticoagulant in a patient with active, significant lower GI bleeding and a falling haemoglobin would worsen the bleeding and is contraindicated.', 1),
('c2000000-0000-0000-0000-000000000013', 'B', 'Withhold pharmacological VTE prophylaxis and use mechanical prophylaxis instead, pending investigation of the bleeding', true, 'Correct. Active, clinically significant gastrointestinal bleeding is a contraindication to pharmacological VTE prophylaxis, as it would worsen bleeding risk. Mechanical methods (e.g., intermittent pneumatic compression, if not contraindicated) should be used instead while the cause of bleeding is investigated, with pharmacological prophylaxis reconsidered once the bleeding has resolved or been controlled.', 2),
('c2000000-0000-0000-0000-000000000013', 'C', 'Start low molecular weight heparin but at a reduced dose', false, 'Ruled out because even a reduced dose of anticoagulant is inappropriate in the context of active, clinically significant bleeding; pharmacological prophylaxis should be withheld entirely until the bleeding is assessed and controlled.', 3),
('c2000000-0000-0000-0000-000000000013', 'D', 'Give no VTE prophylaxis of any kind and mobilise the patient as soon as possible', false, 'Ruled out because he remains at risk of VTE due to reduced mobility and acute illness; mechanical prophylaxis should still be provided even though pharmacological prophylaxis is contraindicated.', 4),
('c2000000-0000-0000-0000-000000000013', 'E', 'Start a direct oral anticoagulant instead of low molecular weight heparin for prophylaxis', false, 'Ruled out because switching to a different anticoagulant does not address the fundamental contraindication of active bleeding; any pharmacological anticoagulant would carry similar risk in this context.', 5),
('c2000000-0000-0000-0000-000000000014', 'A', 'Omeprazole may reduce the antiplatelet effect of clopidogrel via inhibition of its hepatic activation', true, $x$Correct. Clopidogrel is a prodrug that requires hepatic activation via CYP2C19. Omeprazole (and esomeprazole) are potent CYP2C19 inhibitors and can reduce the formation of clopidogrel's active metabolite, potentially reducing its antiplatelet efficacy; where gastric protection is needed alongside clopidogrel, a PPI with less CYP2C19 inhibition (e.g., pantoprazole or lansoprazole) is often preferred.$x$, 1),
('c2000000-0000-0000-0000-000000000014', 'B', 'Omeprazole has no interaction of clinical relevance with clopidogrel', false, $x$Ruled out because there is a recognised pharmacokinetic interaction (via CYP2C19 inhibition) that may reduce clopidogrel's antiplatelet effect, which is of particular concern in patients relying on clopidogrel for secondary stroke prevention.$x$, 2),
('c2000000-0000-0000-0000-000000000014', 'C', 'Omeprazole enhances the antiplatelet effect of clopidogrel, increasing bleeding risk', false, 'Ruled out because the interaction works in the opposite direction: omeprazole reduces the activation (and thus the effect) of clopidogrel, rather than potentiating it.', 3),
('c2000000-0000-0000-0000-000000000014', 'D', 'Omeprazole increases clopidogrel absorption from the gastrointestinal tract', false, $x$Ruled out because the interaction is due to hepatic enzyme inhibition affecting clopidogrel's metabolic activation, not a change in gastrointestinal absorption.$x$, 4),
('c2000000-0000-0000-0000-000000000014', 'E', 'Omeprazole should never be co-prescribed with any antiplatelet agent', false, 'Ruled out because PPIs are frequently and appropriately co-prescribed with antiplatelet agents (including aspirin) for gastroprotection; the specific concern is the CYP2C19 interaction with clopidogrel, not PPIs with antiplatelets in general.', 5),
('c2000000-0000-0000-0000-000000000015', 'A', 'Clarithromycin directly damages skeletal muscle independent of any interaction with simvastatin', false, 'Ruled out because clarithromycin alone is not typically myotoxic; the clinical picture here is explained by a pharmacokinetic interaction that raises simvastatin levels, not a direct independent effect of the antibiotic.', 1),
('c2000000-0000-0000-0000-000000000015', 'B', 'Simvastatin induces the metabolism of clarithromycin, reducing its antibacterial efficacy', false, 'Ruled out because this describes the interaction in the wrong direction and with the wrong effect (efficacy reduction) rather than the clinically relevant issue, which is clarithromycin raising simvastatin levels and causing myotoxicity.', 2),
('c2000000-0000-0000-0000-000000000015', 'C', 'This represents a normal, self-limiting side effect of simvastatin unrelated to the new antibiotic', false, 'Ruled out because the acute, severe presentation coinciding with starting clarithromycin points to a significant drug interaction rather than a coincidental baseline statin side effect.', 3),
('c2000000-0000-0000-0000-000000000015', 'D', 'Clarithromycin inhibits CYP3A4, increasing simvastatin plasma concentration and myopathy/rhabdomyolysis risk', true, 'Correct. Clarithromycin is a potent CYP3A4 inhibitor, and simvastatin is extensively metabolised by CYP3A4; co-administration markedly raises simvastatin plasma levels, increasing the risk of myopathy and rhabdomyolysis (suggested here by severe myalgia and dark urine indicating myoglobinuria). This combination should be avoided; if an antibiotic is needed, the statin should be withheld or an alternative antibiotic/statin chosen.', 4),
('c2000000-0000-0000-0000-000000000015', 'E', 'Clarithromycin displaces simvastatin from plasma protein binding sites, increasing free drug levels', false, 'Ruled out because the clinically important mechanism for this interaction is CYP3A4 enzyme inhibition altering hepatic metabolism, not protein-binding displacement.', 5),
('c2000000-0000-0000-0000-000000000016', 'A', 'Continue both drugs unchanged and recheck potassium in one month', false, 'Ruled out because a potassium of 6.4 mmol/L is a significant abnormality with risk of cardiac arrhythmia; it requires prompt action, not deferred routine monitoring.', 1),
('c2000000-0000-0000-0000-000000000016', 'B', 'Increase the spironolactone dose to improve heart failure outcomes as per guidelines', false, 'Ruled out because increasing a potassium-sparing diuretic in the context of significant hyperkalaemia would worsen the problem and risk a life-threatening arrhythmia.', 2),
('c2000000-0000-0000-0000-000000000016', 'C', 'Stop spironolactone, recheck potassium urgently, and review the need for temporary adjustment of ramipril', true, 'Correct. Combining an ACE inhibitor with a potassium-sparing/aldosterone antagonist diuretic like spironolactone is a recognised cause of significant hyperkalaemia, as both reduce potassium excretion. A potassium of 6.4 mmol/L requires spironolactone to be stopped and potassium rechecked urgently, with consideration of temporarily reducing or holding the ACE inhibitor, even though the patient is currently asymptomatic with a normal ECG, because of the risk of life-threatening arrhythmia.', 3),
('c2000000-0000-0000-0000-000000000016', 'D', 'Stop ramipril only and continue spironolactone at the same dose', false, 'Ruled out because both drugs contribute to hyperkalaemia; the standard approach when significant hyperkalaemia develops on this combination is to stop the aldosterone antagonist (spironolactone) first and reassess, with the ACE inhibitor addressed as part of ongoing management depending on renal function and potassium trend.', 4),
('c2000000-0000-0000-0000-000000000016', 'E', 'No action is needed as spironolactone is protective in heart failure regardless of potassium level', false, 'Ruled out because although spironolactone has proven mortality benefit in heart failure, this benefit must be balanced against the risk of significant hyperkalaemia, which requires monitoring and action when it occurs.', 5),
('c2000000-0000-0000-0000-000000000017', 'A', 'This is an unrelated coincidental viral illness', false, 'Ruled out because the clear pharmacological interaction between trimethoprim and methotrexate, combined with the classic presentation of pancytopenia and mucositis, makes a drug-related cause far more likely than coincidence.', 1),
('c2000000-0000-0000-0000-000000000017', 'B', $x$Trimethoprim potentiated methotrexate's antifolate toxicity, precipitating bone marrow suppression$x$, true, 'Correct. Trimethoprim inhibits dihydrofolate reductase, the same enzyme targeted by methotrexate; co-administration has an additive antifolate effect that can precipitate severe bone marrow suppression (pancytopenia) and mucositis, even after a short antibiotic course. Trimethoprim (and co-trimoxazole) should be avoided in patients on methotrexate, with an alternative antibiotic chosen wherever possible.', 2),
('c2000000-0000-0000-0000-000000000017', 'C', 'Trimethoprim caused a direct allergic reaction unrelated to her methotrexate', false, 'Ruled out because the presentation (pancytopenia, mucositis) is not typical of a simple drug allergy and is specifically explained by the additive antifolate mechanism shared by trimethoprim and methotrexate.', 3),
('c2000000-0000-0000-0000-000000000017', 'D', 'Trimethoprim reduced methotrexate renal clearance, but this has no bearing on toxicity', false, 'Ruled out because although trimethoprim can also reduce renal clearance of methotrexate contributing to higher levels, this option incorrectly states that this has no bearing on toxicity, when in fact both the pharmacodynamic antifolate effect and reduced clearance contribute directly to the toxicity seen.', 4),
('c2000000-0000-0000-0000-000000000017', 'E', 'The rheumatoid arthritis itself has caused this haematological picture, independent of medication', false, 'Ruled out because rheumatoid arthritis alone does not typically cause pancytopenia; the clear temporal relationship with starting trimethoprim points to a drug interaction as the cause.', 5),
('c2000000-0000-0000-0000-000000000018', 'A', 'Neuroleptic malignant syndrome', false, 'Ruled out because neuroleptic malignant syndrome is associated with antipsychotic (dopamine-blocking) drugs and typically causes lead-pipe rigidity rather than clonus and hyperreflexia; there is no antipsychotic exposure here.', 1),
('c2000000-0000-0000-0000-000000000018', 'B', 'Anticholinergic toxicity', false, 'Ruled out because anticholinergic toxicity typically causes dry skin, mydriasis, urinary retention, and confusion without clonus, whereas this patient has sweating (not dry skin) and clonus, fitting serotonin syndrome instead.', 2),
('c2000000-0000-0000-0000-000000000018', 'C', 'Opioid withdrawal', false, 'Ruled out because she has just been started on an opioid (tramadol), not withdrawn from one; the clinical picture also fits serotonin syndrome (clonus, hyperthermia) rather than the classic features of opioid withdrawal (piloerection, diarrhoea, yawning, dilated pupils).', 3),
('c2000000-0000-0000-0000-000000000018', 'D', 'Serotonin syndrome', true, 'Correct. The combination of an SSRI (citalopram) and tramadol (which also has serotonergic activity) increases serotonin syndrome risk. The triad of neuromuscular abnormalities (tremor, clonus), autonomic instability (sweating, fever), and altered mental status (agitation) developing after starting a serotonergic drug in a patient on an SSRI is characteristic; management requires stopping both serotonergic drugs and supportive care.', 4),
('c2000000-0000-0000-0000-000000000018', 'E', 'Simple viral illness with an unrelated tremor', false, 'Ruled out because the specific combination of neuromuscular signs (clonus, tremor), autonomic instability, and altered mental state following the addition of a serotonergic drug to an SSRI is a recognised toxidrome, not a coincidental viral illness.', 5),
('c2000000-0000-0000-0000-000000000019', 'A', 'Rifampicin induces hepatic CYP enzymes, increasing warfarin metabolism and reducing its anticoagulant effect', true, 'Correct. Rifampicin is a potent inducer of hepatic cytochrome P450 enzymes (including CYP2C9, which metabolises warfarin), increasing warfarin clearance and reducing its anticoagulant effect. Patients starting rifampicin while on warfarin typically need substantially higher warfarin doses, with frequent INR monitoring, to maintain therapeutic anticoagulation; this is particularly critical here given his mechanical valve, where sub-therapeutic INR risks valve thrombosis.', 1),
('c2000000-0000-0000-0000-000000000019', 'B', 'The patient has developed vitamin K deficiency due to tuberculosis', false, 'Ruled out because there is no clinical reason given for vitamin K deficiency (such as malnutrition or malabsorption), and the temporal association with starting rifampicin makes enzyme induction the far more likely explanation for a falling INR.', 2),
('c2000000-0000-0000-0000-000000000019', 'C', 'Rifampicin has displaced warfarin from plasma protein binding sites, reducing its effect', false, 'Ruled out because the clinically important mechanism of this interaction is hepatic enzyme induction increasing warfarin metabolism, not protein-binding displacement.', 3),
('c2000000-0000-0000-0000-000000000019', 'D', 'The patient has been non-adherent with his warfarin due to the new diagnosis', false, 'Ruled out because although non-adherence is always a differential for an unexpectedly low INR, the well-recognised pharmacokinetic interaction between rifampicin and warfarin is the most likely explanation given the clear temporal relationship.', 4),
('c2000000-0000-0000-0000-000000000019', 'E', 'Rifampicin inhibits vitamin K absorption from the gut', false, $x$Ruled out because rifampicin's effect on warfarin is via hepatic enzyme induction increasing warfarin clearance, not through altering vitamin K absorption.$x$, 5),
('c2000000-0000-0000-0000-000000000020', 'A', 'Continue digoxin at the same dose and add an antiemetic for symptomatic relief', false, 'Ruled out because continuing digoxin in the presence of a significantly elevated level and clinical toxicity (including bradyarrhythmia) risks life-threatening arrhythmia; the drug must be stopped, not continued with symptomatic treatment only.', 1),
('c2000000-0000-0000-0000-000000000020', 'B', 'Increase the digoxin dose to overcome apparent reduced efficacy', false, 'Ruled out because the digoxin level is elevated, not low, and the clinical picture is one of toxicity rather than under-treatment; increasing the dose would be dangerous.', 2),
('c2000000-0000-0000-0000-000000000020', 'C', 'Stop amiodarone only and continue digoxin unchanged', false, 'Ruled out because although stopping amiodarone removes the ongoing interaction, digoxin itself must also be withheld immediately given the current toxic level and symptoms; simply stopping amiodarone would not address the immediate toxicity.', 3),
('c2000000-0000-0000-0000-000000000020', 'D', 'Reassure her that yellow-tinged vision is a benign finding unrelated to her medications', false, 'Ruled out because xanthopsia (yellow-tinged vision) is a classic feature of digoxin toxicity and, combined with GI symptoms and bradyarrhythmia and a raised digoxin level, indicates significant toxicity requiring action, not reassurance.', 4),
('c2000000-0000-0000-0000-000000000020', 'E', 'Stop digoxin, check renal function and electrolytes, and arrange cardiac monitoring', true, 'Correct. Amiodarone inhibits P-glycoprotein-mediated renal and biliary clearance of digoxin (and also displaces it from tissue binding), roughly doubling digoxin levels; the digoxin dose should typically be halved when amiodarone is started, and failure to do so here has caused digoxin toxicity (nausea, vomiting, xanthopsia, bradyarrhythmia). Digoxin must be stopped, electrolytes (particularly potassium) and renal function checked, and cardiac monitoring arranged given the arrhythmia risk.', 5),
('c2000000-0000-0000-0000-000000000021', 'A', 'He has developed an acute allergic interstitial nephritis unrelated to his regular medications', false, 'Ruled out because although NSAIDs can rarely cause interstitial nephritis, the specific combination of ACE inhibitor, diuretic, and NSAID together causing haemodynamically mediated AKI is the much more likely and classically recognised explanation here.', 1),
('c2000000-0000-0000-0000-000000000021', 'B', 'His hypertension has caused progressive chronic kidney disease unrelated to recent medication changes', false, 'Ruled out because the acute rise in creatinine over a short period, temporally linked to starting regular ibuprofen alongside his existing ACE inhibitor and diuretic, points to an acute haemodynamic insult rather than a slow chronic process.', 2),
('c2000000-0000-0000-0000-000000000021', 'C', 'Bendroflumethiazide alone has caused this degree of renal impairment', false, 'Ruled out because thiazide diuretics alone do not typically cause this magnitude of acute kidney injury; it is the combination with an ACE inhibitor and an NSAID that critically impairs renal perfusion.', 3),
('c2000000-0000-0000-0000-000000000021', 'D', 'Ramipril alone has caused this degree of renal impairment, independent of the other drugs', false, 'Ruled out because although ACE inhibitors can cause AKI in susceptible patients (e.g., renal artery stenosis), the combination with a diuretic and an NSAID together is the recognised and much more likely explanation for this severe, acute deterioration.', 4),
('c2000000-0000-0000-0000-000000000021', 'E', 'The combination of an ACE inhibitor, a diuretic, and an NSAID has impaired renal autoregulation, causing acute kidney injury', true, $x$Correct. This 'triple whammy' combination is a well-recognised cause of acute kidney injury: diuretics reduce circulating volume, ACE inhibitors dilate the efferent glomerular arteriole, and NSAIDs block compensatory afferent arteriolar vasodilation (via prostaglandin inhibition); together these severely impair glomerular perfusion and autoregulation, precipitating AKI, especially in the context of volume depletion or reduced oral intake.$x$, 5),
('c2000000-0000-0000-0000-000000000022', 'A', 'She has developed new renal impairment, reducing phenytoin clearance', false, $x$Ruled out because phenytoin is predominantly hepatically metabolised, and there is no information suggesting new renal impairment; the disproportionate rise is explained by phenytoin's well-recognised saturable, zero-order metabolism.$x$, 1),
('c2000000-0000-0000-0000-000000000022', 'B', 'Phenytoin levels always rise in direct proportion to dose, so this is an expected, proportionate change', false, 'Ruled out because this describes first-order kinetics, which does not apply to phenytoin once its metabolism is saturated; the whole point of this scenario is that the rise is disproportionate to the small dose increase.', 2),
('c2000000-0000-0000-0000-000000000022', 'C', 'She has developed a new drug interaction with an enzyme inhibitor unrelated to the phenytoin dose change', false, $x$Ruled out because no new interacting drug is described; the scenario specifically describes toxicity following a dose increase, which is explained by phenytoin's own saturable kinetics rather than requiring an additional interacting drug.$x$, 3),
('c2000000-0000-0000-0000-000000000022', 'D', 'Phenytoin metabolism becomes saturated at higher doses, so it follows zero-order kinetics with small increases in dose causing disproportionately large rises in plasma level', true, 'Correct. Phenytoin is metabolised by hepatic enzymes that become saturated within or just above the therapeutic range. Once saturated, further metabolism proceeds at a constant rate regardless of concentration (zero-order kinetics), meaning that a small dose increase can produce a disproportionately large rise in plasma level and precipitate toxicity, unlike drugs with first-order kinetics where level rises roughly proportionately to dose.', 4),
('c2000000-0000-0000-0000-000000000022', 'E', 'The phenytoin level result is likely to be a laboratory error given the small dose change', false, 'Ruled out because this response, combined with clinical signs of toxicity (nystagmus, ataxia, slurred speech), is a well-recognised and expected pharmacokinetic phenomenon with phenytoin, not simply a laboratory artefact.', 5),
('c2000000-0000-0000-0000-000000000023', 'A', 'Start directly at the standard maintenance dose, as steady state will be reached quickly regardless of half-life', false, 'Ruled out because for drugs with a long half-life such as digoxin, starting at the maintenance dose alone means it takes several half-lives (potentially many days) to reach a therapeutic steady-state level, which is too slow in this acute situation requiring urgent rate control.', 1),
('c2000000-0000-0000-0000-000000000023', 'B', 'Give a loading dose regimen (an initial larger dose, often in divided doses) followed by a lower maintenance dose', true, 'Correct. Digoxin has a long half-life, meaning that starting at the maintenance dose alone would take many days (approximately 4-5 half-lives) to reach steady-state therapeutic concentration. Giving a loading dose regimen achieves a therapeutic plasma concentration much more rapidly, after which a lower maintenance dose is continued to sustain that level, accounting for ongoing elimination.', 2),
('c2000000-0000-0000-0000-000000000023', 'C', 'Give a single very large one-off dose with no maintenance dosing thereafter', false, 'Ruled out because without ongoing maintenance dosing, the achieved concentration would simply decline as the drug is eliminated; a loading dose must be followed by an appropriate maintenance regimen to sustain the therapeutic effect.', 3),
('c2000000-0000-0000-0000-000000000023', 'D', 'Increase the dosing frequency of the maintenance dose without giving any initial loading dose', false, 'Ruled out because simply increasing the frequency of a maintenance-sized dose does not achieve a rapid rise to therapeutic concentration in the way a specific loading dose strategy does; it still approaches steady state gradually.', 4),
('c2000000-0000-0000-0000-000000000023', 'E', 'Reduce the dose below standard maintenance levels to avoid the need for loading', false, 'Ruled out because reducing the dose would slow, not speed, the achievement of a therapeutic concentration, which is the opposite of what is required in this urgent clinical situation.', 5),
('c2000000-0000-0000-0000-000000000024', 'A', 'Increased contraceptive efficacy due to enhanced absorption of the pill', false, 'Ruled out because rifampicin does not enhance absorption of the contraceptive pill; its clinically important effect is hepatic enzyme induction, which reduces, not increases, hormonal drug levels.', 1),
('c2000000-0000-0000-0000-000000000024', 'B', 'No clinically significant interaction, as rifampicin only affects drugs used for infections', false, $x$Ruled out because rifampicin's enzyme-inducing effect is broad and clinically significant for many hepatically metabolised drugs, including hormonal contraceptives, not limited to anti-infective drugs.$x$, 2),
('c2000000-0000-0000-0000-000000000024', 'C', 'Reduced contraceptive efficacy due to hepatic enzyme induction increasing oestrogen/progestogen metabolism', true, 'Correct. Rifampicin is a potent inducer of hepatic CYP3A4, which increases the metabolism of both the oestrogen and progestogen components of the combined pill, substantially reducing contraceptive efficacy. Women taking rifampicin (even for a short course) should be advised to use additional or alternative contraception (e.g., barrier methods, or a non-hormonal/enzyme-independent method), continuing for a period after stopping rifampicin because enzyme induction persists after the inducing drug is withdrawn.', 3),
('c2000000-0000-0000-0000-000000000024', 'D', 'Increased risk of oestrogen-related side effects such as venous thromboembolism', false, 'Ruled out because enzyme induction reduces, rather than increases, circulating hormone levels, making reduced contraceptive efficacy (and hence pregnancy risk) the relevant concern, not increased oestrogenic side effects.', 4),
('c2000000-0000-0000-0000-000000000024', 'E', 'The interaction only becomes relevant if rifampicin is taken for longer than 6 months', false, 'Ruled out because enzyme induction with rifampicin can become clinically significant within days to a couple of weeks, so contraceptive advice is needed even for shorter courses, such as latent TB treatment or TB prophylaxis regimens.', 5),
('c2000000-0000-0000-0000-000000000025', 'A', 'GTN undergoes extensive hepatic first-pass metabolism if swallowed, so the sublingual route avoids this and allows rapid, effective absorption directly into the systemic circulation', true, 'Correct. GTN is very extensively metabolised by the liver on first pass, so oral swallowing would inactivate most of the dose before it reached the systemic circulation. The sublingual (or buccal/transdermal) route bypasses hepatic first-pass metabolism, allowing rapid absorption directly into the systemic circulation and a fast onset of action, which is essential for treating acute angina symptoms.', 1),
('c2000000-0000-0000-0000-000000000025', 'B', 'GTN is destroyed by gastric acid and would have no effect if swallowed', false, 'Ruled out because the principal reason oral GTN is ineffective is extensive hepatic first-pass metabolism after gut absorption, not destruction by gastric acid.', 2),
('c2000000-0000-0000-0000-000000000025', 'C', 'The sublingual route is used only for patient convenience, with no pharmacokinetic advantage', false, 'Ruled out because the sublingual route provides a genuine pharmacokinetic advantage (avoiding first-pass metabolism and achieving faster onset), not simply a matter of convenience.', 3),
('c2000000-0000-0000-0000-000000000025', 'D', 'Oral GTN would be absorbed too slowly to ever reach a therapeutic level', false, 'Ruled out because the main issue is not the speed of absorption from the gut but that most of the absorbed drug would be inactivated by hepatic first-pass metabolism before reaching the systemic circulation.', 4),
('c2000000-0000-0000-0000-000000000025', 'E', 'GTN causes severe gastrointestinal side effects if swallowed, making sublingual administration necessary', false, 'Ruled out because the primary pharmacokinetic reason for sublingual administration is avoidance of first-pass metabolism, not prevention of gastrointestinal side effects.', 5),
('c2000000-0000-0000-0000-000000000026', 'A', 'Immediately after the first dose, since the drug is given at a fixed maintenance dose', false, 'Ruled out because without a loading dose, a single maintenance dose does not achieve steady-state concentration; it takes several half-lives of repeated dosing for the accumulation and elimination to reach equilibrium.', 1),
('c2000000-0000-0000-0000-000000000026', 'B', 'Approximately 24 hours, equal to one half-life', false, $x$Ruled out because one half-life is the time for the drug's concentration to fall by half after a dose, not the time to reach steady state with repeated dosing; steady state requires roughly 4-5 half-lives.$x$, 2),
('c2000000-0000-0000-0000-000000000026', 'C', 'Steady state will never be reached with once-daily dosing of this drug', false, 'Ruled out because steady state is reached with any regular fixed-interval dosing regimen, including once-daily dosing, provided the drug is given consistently; it will be reached, just not instantaneously.', 3),
('c2000000-0000-0000-0000-000000000026', 'D', 'Approximately 4-5 days, since steady state is generally reached after about 4-5 half-lives of regular dosing', true, 'Correct. With regular dosing at a fixed interval and no loading dose, plasma concentration rises progressively and reaches a stable steady state after approximately 4-5 half-lives of regular dosing, regardless of the dose given at each interval. With a 24-hour half-life, this corresponds to roughly 4-5 days.', 4),
('c2000000-0000-0000-0000-000000000026', 'E', 'Approximately 10-12 days, since steady state requires around 10 half-lives', false, 'Ruled out because the standard approximation for reaching steady state is 4-5 half-lives, not 10; with a 24-hour half-life this would be roughly 4-5 days, not 10-12.', 5),
('c2000000-0000-0000-0000-000000000027', 'A', 'Phenytoin is highly protein-bound, and hypoalbuminaemia increases the free (pharmacologically active) fraction, causing toxicity despite a normal total level', true, $x$Correct. Phenytoin is approximately 90% bound to plasma albumin, with only the small unbound fraction being pharmacologically active. In hypoalbuminaemia (e.g., due to cirrhosis or nephrotic syndrome), less drug is bound, increasing the free fraction and hence the active drug level, even though the total (bound plus unbound) concentration measured on standard assays remains within the 'normal' therapeutic range. Clinically, this requires either measuring free phenytoin levels or adjusting interpretation of the total level in the context of low albumin.$x$, 1),
('c2000000-0000-0000-0000-000000000027', 'B', 'The reported phenytoin level must be a laboratory error, as toxicity cannot occur with a normal total level', false, $x$Ruled out because toxicity with a 'normal' total phenytoin level is a well-recognised phenomenon in hypoalbuminaemia, explained by an increased free fraction, rather than necessarily indicating a laboratory error.$x$, 2),
('c2000000-0000-0000-0000-000000000027', 'C', 'His cirrhosis has caused increased renal clearance of phenytoin, unrelated to protein binding', false, 'Ruled out because phenytoin is predominantly hepatically metabolised, and the relevant mechanism here relates to reduced protein binding (due to hypoalbuminaemia) increasing the free active fraction, not renal clearance.', 3),
('c2000000-0000-0000-0000-000000000027', 'D', 'Cirrhosis has no effect on phenytoin pharmacokinetics or protein binding', false, 'Ruled out because cirrhosis commonly causes hypoalbuminaemia, which directly affects the protein binding (and hence free fraction) of highly protein-bound drugs like phenytoin.', 4),
('c2000000-0000-0000-0000-000000000027', 'E', 'He has developed a new, unrelated neurological condition causing these symptoms', false, 'Ruled out because the clinical features described (nystagmus, ataxia, drowsiness) are classic for phenytoin toxicity, and the physiological explanation of hypoalbuminaemia increasing the free fraction fits the scenario well, making a new unrelated diagnosis far less likely.', 5),
('c2000000-0000-0000-0000-000000000028', 'A', 'She has developed opioid tolerance from previous opioid exposure', false, 'Ruled out because she describes lifelong poor response to codeine specifically, while morphine has always worked well, which points to a specific metabolic difference in codeine activation rather than generalised tolerance to opioids.', 1),
('c2000000-0000-0000-0000-000000000028', 'B', 'She is likely a CYP2D6 poor metaboliser, so codeine is not adequately converted to its active metabolite, morphine', true, $x$Correct. Codeine is a prodrug that requires hepatic conversion via CYP2D6 to morphine to exert most of its analgesic effect. Genetic polymorphisms in CYP2D6 mean some individuals are 'poor metabolisers' who convert very little codeine to morphine, resulting in a poor or absent analgesic response regardless of dose; because morphine itself does not require this conversion, it remains effective in such patients.$x$, 2),
('c2000000-0000-0000-0000-000000000028', 'C', 'Codeine has no analgesic effect in any patient and this is an expected universal finding', false, 'Ruled out because codeine is an effective analgesic in most of the population; the scenario describes an individual variation (poor metabolism), not a universal lack of effect.', 3),
('c2000000-0000-0000-0000-000000000028', 'D', 'She is a CYP2D6 ultra-rapid metaboliser, which reduces the effect of codeine', false, 'Ruled out because ultra-rapid metabolisers convert codeine to morphine more efficiently, which would tend to increase (and risk excessive) effect and toxicity, not cause a poor response as described here.', 4),
('c2000000-0000-0000-0000-000000000028', 'E', 'Her presentation reflects psychological rather than pharmacological factors', false, 'Ruled out because a consistent, lifelong lack of response to codeine specifically, alongside normal response to morphine, has a well-recognised pharmacogenomic explanation (CYP2D6 poor metabolism) rather than being a psychological phenomenon.', 5),
('c2000000-0000-0000-0000-000000000029', 'A', 'Give activated charcoal only, with no other treatment', false, 'Ruled out because activated charcoal is only useful within about 1 hour of ingestion to reduce absorption; at 5 hours post-ingestion with a level above the treatment line, N-acetylcysteine is required to prevent hepatotoxicity, not charcoal alone.', 1),
('c2000000-0000-0000-0000-000000000029', 'B', 'Discharge home with outpatient follow-up, as she is currently asymptomatic', false, 'Ruled out because being asymptomatic does not exclude a significant risk of paracetamol-induced liver injury; her level is above the treatment line, indicating a real risk that requires treatment with N-acetylcysteine, not discharge.', 2),
('c2000000-0000-0000-0000-000000000029', 'C', 'Perform urgent haemodialysis to remove the paracetamol', false, 'Ruled out because haemodialysis is not first-line treatment for paracetamol overdose and is reserved for specific severe cases (e.g., very high levels with severe acidosis or coma); N-acetylcysteine is the standard, effective treatment here.', 3),
('c2000000-0000-0000-0000-000000000029', 'D', 'Await liver function test results before deciding whether to treat', false, 'Ruled out because treatment decisions in acute paracetamol overdose are based on the plasma paracetamol level relative to the treatment nomogram at the appropriate time point, not on waiting for liver function tests to become abnormal, by which time treatment is less effective.', 4),
('c2000000-0000-0000-0000-000000000029', 'E', 'Start intravenous N-acetylcysteine', true, 'Correct. Her plasma paracetamol level plots above the treatment line on the nomogram at a validated time point (4 hours or later post-ingestion), indicating a significant risk of hepatotoxicity. IV N-acetylcysteine should be started promptly, as it is highly effective at preventing hepatotoxicity when given early, by replenishing glutathione stores that detoxify the toxic paracetamol metabolite NAPQI.', 5),
('c2000000-0000-0000-0000-000000000030', 'A', 'Pure respiratory acidosis from respiratory depression', false, 'Ruled out because salicylates stimulate rather than depress the respiratory centre, causing hyperventilation and a low pCO2 (respiratory alkalosis), the opposite of respiratory acidosis.', 1),
('c2000000-0000-0000-0000-000000000030', 'B', 'Pure metabolic alkalosis without respiratory involvement', false, 'Ruled out because salicylate poisoning characteristically also causes a metabolic acidosis (from accumulation of organic acids and uncoupling of oxidative phosphorylation), giving a mixed picture rather than pure alkalosis.', 2),
('c2000000-0000-0000-0000-000000000030', 'C', 'Respiratory alkalosis progressing to a mixed respiratory alkalosis and metabolic acidosis', true, 'Correct. Salicylates directly stimulate the respiratory centre, causing early hyperventilation and respiratory alkalosis (low pCO2, high pH), while also uncoupling oxidative phosphorylation and causing accumulation of organic acids, producing a metabolic acidosis; the two often coexist, giving a mixed picture, and this can progress to a predominant metabolic acidosis as toxicity worsens.', 3),
('c2000000-0000-0000-0000-000000000030', 'D', 'No acid-base disturbance is expected in salicylate poisoning', false, 'Ruled out because salicylate poisoning is a classic cause of a mixed acid-base disturbance (respiratory alkalosis plus metabolic acidosis), which is central to its recognition and management.', 4),
('c2000000-0000-0000-0000-000000000030', 'E', 'Pure metabolic acidosis with a normal anion gap', false, 'Ruled out because salicylate-induced metabolic acidosis is characteristically a raised anion gap metabolic acidosis, and in the early stages it typically coexists with a respiratory alkalosis rather than occurring in isolation.', 5),
('c2000000-0000-0000-0000-000000000031', 'A', 'Give flumazenil to reverse suspected benzodiazepine toxicity', false, 'Ruled out because the clinical picture (pinpoint pupils, needle marks, severe respiratory depression) is characteristic of opioid, not benzodiazepine, toxicity; flumazenil would not address the underlying cause and carries seizure risk in mixed overdoses.', 1),
('c2000000-0000-0000-0000-000000000031', 'B', 'Administer activated charcoal via nasogastric tube', false, 'Ruled out because activated charcoal has no role in reversing acute opioid toxicity from parenteral use, and the priority in this compromised, hypoxic patient is airway/breathing support and naloxone, not charcoal.', 2),
('c2000000-0000-0000-0000-000000000031', 'C', 'Perform immediate haemodialysis to remove the opioid', false, 'Ruled out because haemodialysis is not used in acute opioid overdose; naloxone rapidly and effectively reverses opioid toxicity without the need for dialysis.', 3),
('c2000000-0000-0000-0000-000000000031', 'D', 'Give intravenous or intramuscular naloxone while supporting airway and breathing', true, $x$Correct. This presentation (pinpoint pupils, marked respiratory depression, reduced consciousness, needle marks) is classic for opioid overdose. Naloxone is a competitive opioid receptor antagonist that rapidly reverses respiratory depression and should be given promptly (IV, IM, or intranasal) alongside airway support and oxygen, with repeat doses or an infusion often needed given naloxone's shorter half-life than many opioids.$x$, 4),
('c2000000-0000-0000-0000-000000000031', 'E', 'Observe without treatment, as opioid overdose is usually self-limiting', false, 'Ruled out because severe respiratory depression with hypoxia (SpO2 82%) is immediately life-threatening and requires urgent reversal with naloxone, not simple observation.', 5),
('c2000000-0000-0000-0000-000000000032', 'A', 'Flumazenil should generally be avoided or used with extreme caution, given the risk of seizures, especially in chronic benzodiazepine users or mixed overdoses', true, 'Correct. Flumazenil, a benzodiazepine receptor antagonist, can precipitate acute benzodiazepine withdrawal and seizures in chronic users, and can unmask seizures or arrhythmias in mixed overdoses (e.g., with tricyclic antidepressants or other pro-convulsant drugs, which may be present here given uncertain co-ingestion). It is generally reserved for specific situations (e.g., reversing iatrogenic over-sedation during procedures) rather than routine use in self-poisoning, where supportive care is usually sufficient since respiratory function is not critically compromised.', 1),
('c2000000-0000-0000-0000-000000000032', 'B', 'Flumazenil should be given routinely and immediately to all patients with benzodiazepine overdose', false, 'Ruled out because flumazenil carries significant risks (precipitating seizures/withdrawal) in chronic benzodiazepine users and mixed overdoses, so it is not given routinely to all such patients, particularly when respiratory status is not critically compromised.', 2),
('c2000000-0000-0000-0000-000000000032', 'C', 'Flumazenil is the definitive treatment and should be given in preference to supportive airway management', false, 'Ruled out because supportive care (airway, breathing, monitoring) remains the mainstay of managing benzodiazepine overdose; flumazenil is not a substitute for basic supportive management and carries its own significant risks.', 3),
('c2000000-0000-0000-0000-000000000032', 'D', $x$Flumazenil has no significant risks and can be used freely regardless of the patient's history$x$, false, 'Ruled out because flumazenil has well-recognised risks, particularly precipitating seizures in chronic benzodiazepine users or in mixed overdoses with pro-convulsant co-ingestants.', 4),
('c2000000-0000-0000-0000-000000000032', 'E', 'Flumazenil should be given intramuscularly rather than intravenously to reduce its risks', false, $x$Ruled out because flumazenil's risk profile is not meaningfully altered by changing the route of administration; the key issue is patient selection (avoiding use in chronic users/mixed overdoses), not the route given.$x$, 5),
('c2000000-0000-0000-0000-000000000033', 'A', 'Intravenous flumazenil to reverse sedation', false, 'Ruled out because flumazenil (a benzodiazepine antagonist) has no role in tricyclic antidepressant toxicity and could precipitate seizures in this pro-convulsant overdose; it does not address the cardiotoxicity (QRS widening) seen here.', 1),
('c2000000-0000-0000-0000-000000000033', 'B', 'Intravenous class Ia or Ic antiarrhythmic drugs (e.g., flecainide) to treat the tachycardia', false, 'Ruled out because these antiarrhythmics also block sodium channels and would worsen, not improve, the cardiotoxicity of tricyclic overdose; they are contraindicated in this context.', 2),
('c2000000-0000-0000-0000-000000000033', 'C', 'Immediate synchronised cardioversion for the sinus tachycardia', false, 'Ruled out because sinus tachycardia is not an arrhythmia requiring cardioversion; the priority is treating the underlying sodium channel blockade with sodium bicarbonate, not electrical cardioversion of a sinus rhythm.', 3),
('c2000000-0000-0000-0000-000000000033', 'D', 'Oral activated charcoal only, with no other intervention', false, 'Ruled out because although activated charcoal may be considered if given very early after ingestion, it does not address the current cardiotoxicity; IV sodium bicarbonate is required for QRS widening to reduce the risk of life-threatening arrhythmia.', 4),
('c2000000-0000-0000-0000-000000000033', 'E', 'Intravenous sodium bicarbonate', true, 'Correct. QRS widening in tricyclic antidepressant overdose reflects sodium channel blockade in the myocardium and predicts an increased risk of ventricular arrhythmia and seizures. IV sodium bicarbonate is the first-line treatment: it increases extracellular sodium concentration and alkalinises the blood, both of which help overcome the sodium channel blockade and narrow the QRS complex, reducing arrhythmia risk.', 5),
('c2000000-0000-0000-0000-000000000034', 'A', 'Immediate serum paracetamol level, since this is the most common co-ingestant in children', false, 'Ruled out because there is no suggestion of paracetamol co-ingestion here; the clinically relevant investigation for this scenario, given known ferrous sulfate ingestion, is a serum iron level, not paracetamol.', 1),
('c2000000-0000-0000-0000-000000000034', 'B', 'Serum iron concentration, timed appropriately after ingestion', true, 'Correct. In suspected significant iron overdose, a serum iron concentration (typically taken 4 hours post-ingestion, or immediately if the patient is symptomatic, with the timing chosen to reflect peak absorption) helps determine severity and the need for chelation therapy with desferrioxamine; management is guided by the degree of toxicity (clinical features and iron level) rather than by tablet count alone, which is often unreliable.', 2),
('c2000000-0000-0000-0000-000000000034', 'C', 'Abdominal ultrasound to look for radio-opaque tablets', false, 'Ruled out because ultrasound is not the investigation of choice for detecting ingested iron tablets or guiding management; a serum iron level is the key investigation, and plain abdominal X-ray (not ultrasound) may occasionally show radio-opaque tablets in some cases.', 3),
('c2000000-0000-0000-0000-000000000034', 'D', 'Urine toxicology screen', false, 'Ruled out because standard urine toxicology screens do not reliably detect iron and are not useful for assessing severity of iron overdose; serum iron concentration is the appropriate test.', 4),
('c2000000-0000-0000-0000-000000000034', 'E', 'Arterial blood gas alone, without any iron level', false, 'Ruled out because while a metabolic acidosis can occur in significant iron toxicity and blood gas may be a useful adjunct, it is non-specific; a serum iron concentration is required to specifically assess the degree of iron toxicity and guide chelation decisions.', 5),
('c2000000-0000-0000-0000-000000000035', 'A', 'Intravenous beta-agonist such as salbutamol as the definitive treatment', false, 'Ruled out because beta-agonists act at the same receptor that is blocked in beta-blocker overdose and are often ineffective as monotherapy in severe cases; glucagon (and high-dose insulin-euglycaemia therapy in refractory cases) are the specific treatments used, alongside supportive measures.', 1),
('c2000000-0000-0000-0000-000000000035', 'B', 'Repeat higher-dose atropine as the next step, with no other intervention', false, 'Ruled out because atropine has already been tried with minimal effect; the next appropriate step in refractory beta-blocker-induced bradycardia/hypotension is a specific antidote such as glucagon, rather than simply repeating an ineffective treatment.', 2),
('c2000000-0000-0000-0000-000000000035', 'C', 'Intravenous glucagon', true, 'Correct. In severe symptomatic beta-blocker overdose refractory to atropine, IV glucagon is a recognised specific treatment: it increases intracellular cyclic AMP via a receptor pathway independent of the beta-adrenergic receptor, thereby increasing heart rate and contractility despite beta-blockade, helping to reverse the bradycardia and hypotension.', 3),
('c2000000-0000-0000-0000-000000000035', 'D', 'Intravenous adrenaline as first-line before considering glucagon', false, 'Ruled out because although catecholamines may be used in refractory cases, glucagon is the recognised first specific treatment to try in beta-blocker toxicity refractory to atropine, working through a non-beta-adrenergic mechanism.', 4),
('c2000000-0000-0000-0000-000000000035', 'E', 'Urgent haemodialysis to remove propranolol', false, 'Ruled out because propranolol is highly lipophilic and extensively protein-bound, making it poorly dialysable; haemodialysis is not an effective treatment for propranolol overdose, unlike for some other beta-blockers such as atenolol or sotalol in specific circumstances.', 5),
('c2000000-0000-0000-0000-000000000036', 'A', 'Continue metformin at the same dose, as it does not require renal dose adjustment', false, 'Ruled out because metformin is excreted renally and its accumulation in significant renal impairment increases lactic acidosis risk; it absolutely requires dose adjustment or discontinuation in this context, not continuation unchanged.', 1),
('c2000000-0000-0000-0000-000000000036', 'B', 'Halve the metformin dose and continue monitoring', false, 'Ruled out because with an eGFR this low (22 mL/min/1.73m2) in the context of acute kidney injury, the drug should be stopped altogether during the acute illness rather than continued at a reduced dose.', 2),
('c2000000-0000-0000-0000-000000000036', 'C', 'Stop metformin immediately due to the acute kidney injury', true, 'Correct. Metformin is renally excreted, and its accumulation in significant renal impairment (particularly acute kidney injury or eGFR below around 30 mL/min/1.73m2) increases the risk of lactic acidosis, a rare but potentially fatal complication. Metformin should be withheld during acute illness with AKI and only restarted once renal function has recovered and stabilised.', 3),
('c2000000-0000-0000-0000-000000000036', 'D', 'Switch metformin to an equivalent dose of a sulfonylurea without addressing renal function', false, 'Ruled out because although sulfonylureas may need dose adjustment in renal impairment too and carry hypoglycaemia risk, the immediate priority stated in the question is appropriate action regarding metformin itself, which should be stopped given the acute kidney injury; management of glycaemic control can be addressed separately once metformin is withheld.', 4),
('c2000000-0000-0000-0000-000000000036', 'E', 'Continue metformin and start regular monitoring of serum lactate only', false, 'Ruled out because monitoring lactate does not prevent the risk; the appropriate action is to stop metformin during this acute illness with significant renal impairment, not to continue it with monitoring alone.', 5),
('c2000000-0000-0000-0000-000000000037', 'A', 'Advise against regular NSAID use and suggest paracetamol or another non-nephrotoxic analgesic instead', true, 'Correct. NSAIDs reduce renal prostaglandin-mediated afferent arteriolar vasodilation, which can significantly worsen renal perfusion and function in patients with pre-existing chronic kidney disease, risking acute deterioration in renal function. Regular NSAID use should generally be avoided in CKD, especially at more advanced stages, with alternative analgesics such as paracetamol (with careful consideration of other options if inadequate) preferred.', 1),
('c2000000-0000-0000-0000-000000000037', 'B', 'Prescribe regular ibuprofen at the standard adult dose with no monitoring required', false, 'Ruled out because regular NSAID use in a patient with stage 3b CKD carries a significant risk of further worsening renal function and should be avoided rather than prescribed without caution.', 2),
('c2000000-0000-0000-0000-000000000037', 'C', 'Suggest ibuprofen only if taken with a proton pump inhibitor for gastric protection, with no other precautions', false, 'Ruled out because a PPI addresses gastrointestinal risk, not the renal risk of NSAIDs in CKD; the main concern in this patient is nephrotoxicity, which is not mitigated by gastric protection.', 3),
('c2000000-0000-0000-0000-000000000037', 'D', 'Advise that NSAIDs are safe in CKD provided they are used for less than 2 weeks', false, 'Ruled out because even relatively short courses of NSAIDs can precipitate acute deterioration in renal function in patients with significant pre-existing CKD; caution and avoidance (not simply a duration limit) is the appropriate general advice.', 4),
('c2000000-0000-0000-0000-000000000037', 'E', 'Recommend switching to a higher dose of aspirin instead, as it is safer for the kidneys than ibuprofen', false, 'Ruled out because aspirin at high anti-inflammatory doses shares similar prostaglandin-mediated renal risks to other NSAIDs and is not a safer alternative in this context.', 5),
('c2000000-0000-0000-0000-000000000038', 'A', 'Reduced antibacterial efficacy due to renal impairment', false, $x$Ruled out because renal impairment does not typically reduce gentamicin's antibacterial efficacy; the clinically important risk is drug accumulation and toxicity (nephrotoxicity, ototoxicity) from reduced clearance, not reduced efficacy.$x$, 1),
('c2000000-0000-0000-0000-000000000038', 'B', 'Accumulation of gentamicin due to reduced renal clearance, increasing the risk of nephrotoxicity and ototoxicity', true, 'Correct. Gentamicin is renally excreted, and in renal impairment, standard dosing without adjustment for renal function and without monitoring drug levels risks significant drug accumulation. This increases the risk of further nephrotoxicity (potentially worsening renal function further, in a vicious cycle) and ototoxicity (which can be irreversible). Gentamicin dosing must be adjusted based on renal function, with trough (and sometimes peak) levels monitored to guide dosing interval and further doses.', 2),
('c2000000-0000-0000-0000-000000000038', 'C', 'Increased risk of allergic anaphylactic reaction due to renal impairment', false, 'Ruled out because renal impairment does not increase the risk of an allergic reaction to gentamicin; the specific risk introduced by inappropriate dosing in renal impairment is toxicity from drug accumulation, not allergy.', 3),
('c2000000-0000-0000-0000-000000000038', 'D', 'Increased risk of hepatotoxicity from gentamicin accumulation', false, 'Ruled out because gentamicin is not hepatotoxic; the accumulation risk in renal impairment specifically relates to nephrotoxicity and ototoxicity, given its renal route of excretion.', 4),
('c2000000-0000-0000-0000-000000000038', 'E', 'No significant additional risk, as gentamicin dosing is not affected by renal function', false, 'Ruled out because gentamicin dosing very much depends on renal function; failing to adjust for renal impairment is a recognised and significant prescribing error with serious toxicity risk.', 5),
('c2000000-0000-0000-0000-000000000039', 'A', 'Progression of her underlying cancer causing new neurological symptoms', false, 'Ruled out because the combination of drowsiness, pinpoint pupils, and respiratory depression developing after starting morphine in a patient with significant renal impairment is a classic pattern of opioid toxicity from metabolite accumulation, which is a more likely and directly treatable explanation.', 1),
('c2000000-0000-0000-0000-000000000039', 'B', 'She has developed an unrelated stroke', false, 'Ruled out because pinpoint pupils and respiratory depression are not typical features of stroke, whereas they are classic for opioid toxicity, which fits the clinical context of renal impairment and recent morphine initiation.', 2),
('c2000000-0000-0000-0000-000000000039', 'C', 'This is an expected, harmless effect of morphine that requires no action', false, 'Ruled out because significant sedation with respiratory depression is a serious, potentially life-threatening adverse effect requiring prompt action (reducing/stopping the opioid, considering naloxone if severe), not something to be disregarded.', 3),
('c2000000-0000-0000-0000-000000000039', 'D', 'Accumulation of active morphine metabolites due to reduced renal clearance, causing opioid toxicity', true, 'Correct. Morphine is metabolised to active metabolites (including morphine-6-glucuronide), which are renally excreted. In significant renal impairment, these active metabolites accumulate, causing opioid toxicity (sedation, respiratory depression, miosis) even without a change in the morphine dose. Opioids that rely less on renal clearance of active metabolites (e.g., oxycodone with caution, or fentanyl/alfentanil in severe renal impairment) are generally preferred in advanced CKD, at reduced doses with careful titration.', 4),
('c2000000-0000-0000-0000-000000000039', 'E', 'She has developed a new lower respiratory tract infection unrelated to her morphine', false, 'Ruled out because although infection is always a differential for deterioration, the specific combination of drowsiness, pinpoint pupils, and respiratory depression following morphine initiation in renal impairment is much more consistent with opioid toxicity from metabolite accumulation.', 5),
('c2000000-0000-0000-0000-000000000040', 'A', 'Digoxin toxicity is unrelated to renal function and reflects an idiosyncratic reaction', false, 'Ruled out because digoxin toxicity in this context is directly and predictably related to reduced renal clearance in a patient with significant CKD, not an unpredictable idiosyncratic reaction.', 1),
('c2000000-0000-0000-0000-000000000040', 'B', 'The digoxin level is falsely elevated due to a laboratory assay error and does not reflect true toxicity', false, 'Ruled out because the clinical features (nausea, vomiting, bradycardia) are consistent with the elevated digoxin level, making genuine toxicity from renally impaired clearance the far more likely explanation than a laboratory error.', 2),
('c2000000-0000-0000-0000-000000000040', 'C', 'His renal impairment has no bearing on digoxin dosing, and toxicity is due to an unrelated cause', false, 'Ruled out because renal function is a key determinant of appropriate digoxin dosing, and this scenario specifically demonstrates toxicity resulting from failure to adjust the dose for his reduced eGFR.', 3),
('c2000000-0000-0000-0000-000000000040', 'D', 'He required a higher, not lower, starting dose given his atrial fibrillation was poorly controlled', false, 'Ruled out because increasing the dose further would worsen toxicity; the issue is that the standard dose was already too high for his renal function, requiring a reduction, not an increase.', 4),
('c2000000-0000-0000-0000-000000000040', 'E', 'Digoxin is predominantly renally excreted, and the standard dose was too high for his level of renal impairment, causing accumulation and toxicity', true, 'Correct. Digoxin is mainly eliminated unchanged by the kidneys, so its dose must be reduced in renal impairment to avoid accumulation and toxicity. Prescribing the standard dose without adjusting for his significantly reduced eGFR has resulted in supratherapeutic levels and clinical toxicity (nausea, vomiting, bradycardia); the dose should have been reduced and levels monitored from the outset.', 5),
('c2000000-0000-0000-0000-000000000041', 'A', 'Codeine is completely safe in hepatic impairment as it is renally, not hepatically, cleared', false, $x$Ruled out because codeine undergoes hepatic metabolism (including CYP2D6-mediated activation to morphine) and its use in significant hepatic impairment carries risk of accumulation and precipitating encephalopathy; it is not simply renally cleared and 'completely safe.'$x$, 1),
('c2000000-0000-0000-0000-000000000041', 'B', 'The main concern is reduced analgesic efficacy of codeine in liver disease, not any safety issue', false, 'Ruled out because the primary and most significant concern in this scenario is the risk of precipitating or worsening hepatic encephalopathy through sedation and reduced clearance, not simply reduced efficacy.', 2),
('c2000000-0000-0000-0000-000000000041', 'C', 'Opioids can precipitate or worsen hepatic encephalopathy and should be used cautiously at reduced doses, or avoided, in patients with significant hepatic impairment', true, 'Correct. Opioids are sedating and can worsen conscious level and precipitate or exacerbate hepatic encephalopathy in patients with significant liver disease, partly through reduced hepatic clearance leading to drug/metabolite accumulation and partly through their central sedative effect. In this patient with known hepatic encephalopathy, opioids should be used with great caution, at reduced doses if used at all, with close monitoring, and alternative analgesic strategies considered where possible.', 3),
('c2000000-0000-0000-0000-000000000041', 'D', 'Opioids should be avoided in all patients with any chronic pain condition regardless of liver function', false, 'Ruled out because this overstates the concern; opioids are frequently and appropriately used for significant pain in patients without hepatic impairment, and the specific issue here relates to his hepatic impairment and encephalopathy risk, not opioid use in general.', 4),
('c2000000-0000-0000-0000-000000000041', 'E', 'There is no specific concern, as encephalopathy is unrelated to medication choice in cirrhosis', false, 'Ruled out because sedating drugs, including opioids and benzodiazepines, are well-recognised precipitants of hepatic encephalopathy in patients with cirrhosis, making drug choice highly relevant.', 5),
('c2000000-0000-0000-0000-000000000042', 'A', 'Recheck renal function and potassium within 1-2 weeks of starting the ACE inhibitor', true, 'Correct. ACE inhibitors can cause a rise in creatinine and potassium, particularly in patients with pre-existing renal impairment, renovascular disease, or those also on other renin-angiotensin-affecting drugs or diuretics. Renal function and potassium should be checked before starting and rechecked within 1-2 weeks of initiation (and after any dose increase) to detect a significant deterioration or hyperkalaemia early, before it becomes clinically significant.', 1),
('c2000000-0000-0000-0000-000000000042', 'B', 'No monitoring is required unless the patient becomes symptomatic', false, 'Ruled out because clinically significant deterioration in renal function or hyperkalaemia can occur without symptoms in the early stages; routine monitoring after starting an ACE inhibitor is standard practice, especially in a patient with pre-existing CKD.', 2),
('c2000000-0000-0000-0000-000000000042', 'C', 'Recheck renal function and potassium after 6 months, in line with routine annual review', false, 'Ruled out because this interval is far too long to detect an early, clinically significant deterioration after starting an ACE inhibitor; monitoring should occur within 1-2 weeks of initiation.', 3),
('c2000000-0000-0000-0000-000000000042', 'D', 'Only monitor blood pressure, as this is the main therapeutic target', false, 'Ruled out because although blood pressure response is relevant, renal function and potassium monitoring are specifically required due to the known risks of ACE inhibitors in this context, not just blood pressure.', 4),
('c2000000-0000-0000-0000-000000000042', 'E', 'Stop the ACE inhibitor immediately, as CKD is an absolute contraindication', false, 'Ruled out because CKD is not an absolute contraindication to ACE inhibitors; in fact, they are often beneficial for renoprotection in CKD, but do require closer monitoring after initiation, not automatic discontinuation.', 5),
('c2000000-0000-0000-0000-000000000043', 'A', 'Always round insulin doses to the nearest 50 units for simplicity', false, $x$Ruled out because arbitrarily rounding insulin doses to large increments would itself be dangerous and inappropriate; insulin doses must be individualised precisely, and the correct fix for this specific error is avoiding the 'U' abbreviation, not changing dosing practice.$x$, 1),
('c2000000-0000-0000-0000-000000000043', 'B', 'Only prescribe insulin verbally to nursing staff to avoid handwriting issues', false, $x$Ruled out because verbal orders are a recognised source of medication error (due to mishearing) and are generally discouraged for high-risk medications like insulin; clear written prescriptions using the word 'units' in full are the appropriate solution.$x$, 2),
('c2000000-0000-0000-0000-000000000043', 'C', 'Switch all patients to intravenous insulin infusions to avoid subcutaneous dosing errors', false, $x$Ruled out because this is a disproportionate response to a specific, well-recognised abbreviation error; the correct fix is a simple prescribing practice change (writing 'units' in full), not converting all patients to a different, higher-risk route of administration.$x$, 3),
('c2000000-0000-0000-0000-000000000043', 'D', 'Allow doses to be prescribed in millilitres of insulin solution rather than units', false, 'Ruled out because prescribing insulin in millilitres rather than units is itself a recognised source of dangerous dosing errors, as insulin concentration can vary between preparations; insulin should always be prescribed in units, written in full.', 4),
('c2000000-0000-0000-0000-000000000043', 'E', $x$Always write 'units' in full, never abbreviating as 'U' or 'IU', when prescribing insulin$x$, true, $x$Correct. The abbreviation 'U' for units is a well-recognised cause of serious, sometimes fatal, tenfold dosing errors in insulin prescribing, because a handwritten or poorly formatted 'U' can be misread as a zero (or 'IU' misread as '10'). National guidance requires the word 'units' to always be written in full when prescribing insulin, never abbreviated, to eliminate this specific risk.$x$, 5),
('c2000000-0000-0000-0000-000000000044', 'A', 'The main risk is local irritation and phlebitis at the injection site, with no systemic danger', false, 'Ruled out because although local irritation can occur with peripheral potassium infusions, the far more significant and life-threatening risk of an undiluted rapid bolus is fatal cardiac arrhythmia, not simply local site irritation.', 1),
('c2000000-0000-0000-0000-000000000044', 'B', 'Rapid undiluted intravenous potassium chloride can cause fatal cardiac arrhythmia, including cardiac arrest', true, 'Correct. Concentrated potassium chloride given as a rapid, undiluted intravenous bolus is extremely dangerous and can cause immediate, life-threatening hyperkalaemic cardiac arrhythmias, including cardiac arrest. Potassium replacement must always be given as a properly diluted infusion at a controlled rate, and concentrated potassium ampoules are treated as a high-risk medication requiring special storage and double-checking in most hospitals.', 2),
('c2000000-0000-0000-0000-000000000044', 'C', 'There is no significant danger, as potassium is a normal body electrolyte that cannot cause harm', false, $x$Ruled out because although potassium is a normal electrolyte, giving it as a concentrated rapid intravenous bolus causes a dangerous, rapid rise in extracellular potassium that can trigger fatal arrhythmias, regardless of it being a 'natural' substance.$x$, 3),
('c2000000-0000-0000-0000-000000000044', 'D', 'The main risk is an allergic anaphylactic reaction to potassium chloride', false, 'Ruled out because potassium chloride does not typically cause anaphylaxis; the specific, well-recognised danger of undiluted rapid IV administration is cardiotoxicity from an acute rise in serum potassium.', 4),
('c2000000-0000-0000-0000-000000000044', 'E', 'This is an accepted, standard method of giving urgent potassium replacement in all patients', false, $x$Ruled out because rapid undiluted IV potassium chloride bolus is never an accepted standard method of replacement; it is a recognised 'never event'-type error that must always be avoided, regardless of urgency, with diluted, rate-controlled infusion used instead.$x$, 5),
('c2000000-0000-0000-0000-000000000045', 'A', 'An expected interaction between amlodipine and her new ACE inhibitor, unrelated to any transcription error', false, 'Ruled out because amlodipine does not itself cause significant hyperkalaemia; the mechanism here is that amiloride (a potassium-sparing diuretic), not amlodipine, was inadvertently prescribed due to a look-alike/sound-alike error, and this combined with the ACE inhibitor to cause hyperkalaemia.', 1),
('c2000000-0000-0000-0000-000000000045', 'B', 'Her heart failure alone is sufficient to explain the hyperkalaemia, independent of medication changes', false, 'Ruled out because heart failure itself does not typically cause this degree of hyperkalaemia; the combination of an inadvertently prescribed potassium-sparing diuretic and a new ACE inhibitor is the much more likely and directly relevant explanation.', 2),
('c2000000-0000-0000-0000-000000000045', 'C', 'She has developed acute kidney injury unrelated to any prescribing error', false, 'Ruled out because although renal function should be checked, the scenario specifically describes a name-based prescribing error (amlodipine mistaken for amiloride) as the key contributing factor, which is the focus of this question.', 3),
('c2000000-0000-0000-0000-000000000045', 'D', 'A look-alike/sound-alike prescribing error, mistaking amlodipine for amiloride during medication reconciliation', true, 'Correct. Amlodipine (a calcium channel blocker) and amiloride (a potassium-sparing diuretic) are a recognised look-alike/sound-alike (LASA) drug pair that are easily confused, especially when transcribing from handwritten notes without verifying against the original indication or a reliable medication list. This error resulted in the patient inadvertently receiving a potassium-sparing diuretic instead of her usual calcium channel blocker, which combined with a newly started ACE inhibitor to cause significant hyperkalaemia.', 4),
('c2000000-0000-0000-0000-000000000045', 'E', 'This represents an expected side effect of amlodipine that all patients should be warned about', false, 'Ruled out because amlodipine is not associated with significant hyperkalaemia; the adverse outcome arose because a different drug (amiloride) was mistakenly prescribed in its place.', 5),
('c2000000-0000-0000-0000-000000000046', 'A', 'Co-amoxiclav is safe in patients with penicillin allergy because it also contains a beta-lactamase inhibitor', false, 'Ruled out because co-amoxiclav contains amoxicillin, a penicillin, and is absolutely contraindicated in patients with a history of severe penicillin allergy; the beta-lactamase inhibitor component does not remove this risk.', 1),
('c2000000-0000-0000-0000-000000000046', 'B', 'Allergy status must always be actively checked and documented before prescribing any new medication, particularly antibiotics', true, 'Correct. This incident represents a preventable, serious medication safety failure caused by not checking a clearly documented, severe drug allergy before prescribing a related medication (co-amoxiclav contains amoxicillin, a penicillin). Checking and documenting allergy status is a fundamental, non-negotiable step before prescribing any drug, and systems (allergy alerts in electronic prescribing, allergy wristbands, clear chart documentation) should be used to support this, but ultimately the prescriber must actively check.', 2),
('c2000000-0000-0000-0000-000000000046', 'C', 'This reaction was unpredictable and could not have been prevented with better practice', false, 'Ruled out because the allergy was clearly documented in advance; this was an entirely preventable error caused by failure to check that documentation before prescribing, not an unpredictable event.', 3),
('c2000000-0000-0000-0000-000000000046', 'D', 'Only nursing staff, not doctors, are responsible for checking allergy status before drug administration', false, 'Ruled out because checking allergy status is a shared responsibility across the prescribing and administering process, but the prescribing doctor bears primary responsibility for checking allergies before writing the prescription in the first place.', 4),
('c2000000-0000-0000-0000-000000000046', 'E', 'Allergy checks are only necessary when prescribing medications the patient has never taken before', false, 'Ruled out because allergy checks must be performed before every new prescription regardless of whether the specific drug has been taken before, particularly for drug classes (like penicillins) with cross-reactivity and severe reaction potential.', 5),
('c2000000-0000-0000-0000-000000000047', 'A', $x$Ensuring patients are told to take methotrexate 'as needed' for symptom flares$x$, false, $x$Ruled out because oral methotrexate for rheumatoid arthritis is taken on a fixed weekly schedule as a disease-modifying drug, not on an 'as needed' basis for flares; this description does not address the specific once-weekly versus once-daily dosing error at the heart of this incident.$x$, 1),
('c2000000-0000-0000-0000-000000000047', 'B', 'Switching all patients on methotrexate to the intravenous route to avoid oral dosing confusion', false, 'Ruled out because this is a disproportionate response to a documentation/transcription error; the fix is clearer, safer documentation and dedicated safety checks for methotrexate, not a wholesale change in route for all patients.', 2),
('c2000000-0000-0000-0000-000000000047', 'C', 'No specific additional safety measure is needed beyond standard discharge summary practice, as this was an isolated error', false, 'Ruled out because daily-instead-of-weekly methotrexate dosing errors are a well-recognised, recurrent patient safety issue, which is precisely why methotrexate is designated a high-risk medication requiring specific additional safeguards, not treated as a one-off isolated event.', 3),
('c2000000-0000-0000-0000-000000000047', 'D', 'Clear, unambiguous documentation of the weekly dosing schedule and the specific day of the week, with dedicated safety checks for methotrexate prescriptions', true, 'Correct. Oral methotrexate for conditions like rheumatoid arthritis is dosed once weekly, and mistaking this for a daily dose is a well-recognised, potentially fatal prescribing error causing severe toxicity (bone marrow suppression, mucositis, multi-organ failure). Methotrexate is treated as a high-risk medication in most healthcare systems, requiring clear documentation of the specific weekly dosing day, patient education (methotrexate treatment booklets/alert cards), and additional checks (e.g., pharmacist verification) at every point of prescribing, dispensing, and discharge summary preparation.', 4),
('c2000000-0000-0000-0000-000000000047', 'E', 'Discontinuing methotrexate permanently for all patients who experience a transcription error', false, 'Ruled out because the appropriate response to a transcription error is correcting the error and implementing safeguards to prevent recurrence, not permanently discontinuing an effective disease-modifying drug for the underlying condition.', 5),
('c2000000-0000-0000-0000-000000000048', 'A', 'Proceed with administering the vincristine intrathecally as prescribed, since it is written on the chart', false, 'Ruled out because administering vincristine intrathecally is essentially always fatal and must never occur regardless of what is written on a prescription; any such prescription must be immediately identified and corrected before any administration occurs.', 1),
('c2000000-0000-0000-0000-000000000048', 'B', 'Give a reduced dose of vincristine intrathecally to minimise risk', false, 'Ruled out because there is no safe dose of intrathecal vincristine; any intrathecal administration of vincristine, regardless of dose, is essentially uniformly fatal and must be avoided entirely.', 2),
('c2000000-0000-0000-0000-000000000048', 'C', 'Immediately halt the process and alert the prescribing team, as intrathecal vincristine is invariably fatal and must never be given by this route', true, $x$Correct. Vincristine must only ever be given intravenously; inadvertent intrathecal administration is almost universally fatal, causing an ascending, irreversible encephalomyelopathy. This is recognised as a 'never event' in patient safety terms, and there must be system safeguards (physical separation of intrathecal and intravenous chemotherapy in time and space, distinct labelling, and independent checks by staff specifically trained and authorised for intrathecal chemotherapy) to prevent this error; here, immediate action is required to correct the prescription and prevent any possibility of the vincristine being given intrathecally.$x$, 3),
('c2000000-0000-0000-0000-000000000048', 'D', 'Administer the intrathecal methotrexate and the intravenous vincristine at the same time, in the same room, for efficiency', false, 'Ruled out because national safety guidance requires strict separation (in time, location, and staff/equipment) of intrathecal and intravenous chemotherapy procedures specifically to prevent this kind of fatal route error, so combining them for efficiency is directly contrary to safe practice.', 4),
('c2000000-0000-0000-0000-000000000048', 'E', 'Delay only until the next working day, then proceed with the intrathecal vincristine as originally written', false, 'Ruled out because delaying does not resolve the fundamental, life-threatening error; intrathecal vincristine must never be administered under any circumstances or at any time; the prescription must be corrected, not simply postponed.', 5),
('c2000000-0000-0000-0000-000000000049', 'A', 'A new unrelated viral gastroenteritis causing his symptoms', false, 'Ruled out because although gastroenteritis can cause vomiting, the specific combination of hypotension, vomiting, and profound lethargy occurring after abrupt cessation of long-term steroids in a patient with likely HPA axis suppression is much more consistent with adrenal crisis than a coincidental viral illness.', 1),
('c2000000-0000-0000-0000-000000000049', 'B', 'Reactivation of his underlying polymyalgia rheumatica causing systemic illness', false, 'Ruled out because polymyalgia rheumatica itself does not typically cause this acute, severe presentation with hypotension; the clinical picture and clear precipitant (abrupt steroid withdrawal) point to adrenal crisis instead.', 2),
('c2000000-0000-0000-0000-000000000049', 'C', 'An expected, harmless withdrawal reaction from stopping prednisolone that will resolve spontaneously', false, 'Ruled out because this presentation represents a potentially fatal adrenal crisis requiring urgent treatment (IV hydrocortisone and fluids), not a benign, self-limiting withdrawal phenomenon.', 3),
('c2000000-0000-0000-0000-000000000049', 'D', 'Sepsis originating from his prior hospital admission, unrelated to his steroid use', false, 'Ruled out because although sepsis should always be considered and excluded, the clear temporal relationship with abrupt cessation of long-term corticosteroids makes adrenal crisis the most likely and specifically testable explanation here.', 4),
('c2000000-0000-0000-0000-000000000049', 'E', 'Acute adrenal insufficiency (adrenal crisis) due to abrupt cessation of long-term corticosteroid therapy', true, $x$Correct. Long-term corticosteroid use suppresses the hypothalamic-pituitary-adrenal axis, impairing the body's own cortisol production. Abrupt discontinuation, as has happened here due to a discharge documentation error omitting his regular prednisolone, can precipitate a life-threatening adrenal crisis (hypotension, vomiting, lethargy, and potentially collapse). Long-term corticosteroids must never be stopped abruptly and require gradual tapering, with all patients on such treatment carrying a steroid card and having their regular steroid dose clearly documented and continued at every transition of care.$x$, 5),
('c2000000-0000-0000-0000-000000000050', 'A', $x$Writing the unit clearly and in full ('micrograms', not abbreviated), and double-checking doses of high-risk drugs against standard reference ranges before prescribing$x$, true, $x$Correct. Confusing milligrams and micrograms is a well-recognised, potentially fatal prescribing error, particularly for potent drugs like fentanyl where the therapeutic dose is in the microgram range; a thousand-fold overdose would be catastrophic. Best practice includes always writing units in full (avoiding ambiguous abbreviations such as 'mcg' being confused with 'mg'), and checking any unfamiliar or high-risk drug dose against a reliable reference source before prescribing.$x$, 1),
('c2000000-0000-0000-0000-000000000050', 'B', 'Prescribing all opioids exclusively by body weight to standardise dosing', false, 'Ruled out because weight-based dosing does not address the specific problem here, which is a unit-of-measurement error (milligrams vs micrograms), not an issue of weight-based dose calculation.', 2),
('c2000000-0000-0000-0000-000000000050', 'C', 'Avoiding the use of fentanyl altogether in clinical practice due to its potency', false, 'Ruled out because fentanyl is a valuable and commonly used analgesic when prescribed correctly; the appropriate response to this type of error is safer prescribing practice (clear units, checking references), not avoiding the drug entirely.', 3),
('c2000000-0000-0000-0000-000000000050', 'D', 'Relying on nursing staff to identify and correct all such errors before administration', false, 'Ruled out because although this vigilance is valuable and did prevent harm in this case, it should not be relied upon as the primary safeguard; the prescriber must take primary responsibility for writing an accurate, unambiguous prescription in the first place.', 4),
('c2000000-0000-0000-0000-000000000050', 'E', 'Only prescribing fentanyl in liquid oral form to avoid dosing confusion', false, 'Ruled out because changing the formulation does not address the underlying issue of unit confusion between milligrams and micrograms; the fix is clear, unambiguous unit documentation and dose verification, regardless of formulation.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('c2000000-0000-0000-0000-000000000001', 'ACE inhibitor cough is caused by reduced breakdown of bradykinin/substance P, not by histamine or IgE-mediated mechanisms.', 1),
('c2000000-0000-0000-0000-000000000001', 'Switching to an ARB is appropriate because ARBs block the angiotensin II receptor directly and do not affect bradykinin metabolism.', 2),
('c2000000-0000-0000-0000-000000000001', 'Cough typically develops within weeks of starting an ACE inhibitor and resolves within days after stopping it.', 3),
('c2000000-0000-0000-0000-000000000002', 'Statin myopathy ranges from mild myalgia with normal CK to rhabdomyolysis with CK >10x the upper limit of normal; a CK in the thousands warrants stopping the statin and monitoring renal function.', 1),
('c2000000-0000-0000-0000-000000000002', 'Risk factors for statin myopathy include high dose, interacting drugs (e.g., macrolides, fibrates), hypothyroidism, and renal/hepatic impairment.', 2),
('c2000000-0000-0000-0000-000000000002', 'Once symptoms and CK resolve, a lower dose or an alternative statin may be cautiously reintroduced, but not while CK remains grossly elevated.', 3),
('c2000000-0000-0000-0000-000000000003', 'NSAIDs and aspirin both inhibit COX-1, reducing protective prostaglandins in the gastric mucosa; combining them markedly increases ulcer and bleeding risk compared with either drug alone.', 1),
('c2000000-0000-0000-0000-000000000003', 'Risk factors for NSAID-induced GI bleeding include age >65, prior peptic ulcer disease, concurrent aspirin/anticoagulant/corticosteroid use, and Helicobacter pylori infection.', 2),
('c2000000-0000-0000-0000-000000000003', 'Patients at high GI risk who require an NSAID should be co-prescribed a proton pump inhibitor and, where possible, use the lowest effective dose for the shortest duration.', 3),
('c2000000-0000-0000-0000-000000000004', 'Amiodarone contains a large iodine load and can cause both hypothyroidism (more common) and thyrotoxicosis via different mechanisms.', 1),
('c2000000-0000-0000-0000-000000000004', 'Thyroid function should be checked before starting amiodarone and then every 6 months during treatment.', 2),
('c2000000-0000-0000-0000-000000000004', 'Amiodarone-induced thyrotoxicosis often requires specialist endocrinology input and may necessitate stopping amiodarone if a suitable alternative antiarrhythmic exists.', 3),
('c2000000-0000-0000-0000-000000000005', 'Anaphylaxis is recognised by the combination of acute airway/breathing/circulatory compromise, typically with skin or mucosal changes, following exposure to a trigger.', 1),
('c2000000-0000-0000-0000-000000000005', 'Intramuscular adrenaline (adrenaline 1:1000, into the anterolateral thigh) is the first-line treatment and should be given as soon as anaphylaxis is suspected, repeated after 5 minutes if there is no improvement.', 2),
('c2000000-0000-0000-0000-000000000005', $x$The causative drug must be documented clearly as an allergy in the patient's records to prevent re-exposure.$x$, 3),
('c2000000-0000-0000-0000-000000000006', 'Methotrexate is a folate antagonist; toxicity classically causes mucositis (mouth ulcers, sore throat) and bone marrow suppression, and regular full blood count monitoring is mandatory during treatment.', 1),
('c2000000-0000-0000-0000-000000000006', 'Folinic acid (calcium folinate/leucovorin) rescue is used to treat methotrexate toxicity, distinct from routine folic acid supplementation which is given on a different day to reduce common side effects.', 2),
('c2000000-0000-0000-0000-000000000006', 'Risk factors for methotrexate toxicity include renal impairment, drug interactions (e.g., trimethoprim), missed monitoring, and dosing errors (daily instead of weekly).', 3),
('c2000000-0000-0000-0000-000000000007', 'Neuroleptic malignant syndrome typically develops within days of starting or increasing the dose of an antipsychotic and features rigidity, hyperthermia, autonomic instability, and altered consciousness, with markedly raised CK.', 1),
('c2000000-0000-0000-0000-000000000007', 'Management requires immediate withdrawal of the offending drug, supportive care (cooling, IV fluids), and consideration of dantrolene or bromocriptine in severe cases.', 2),
('c2000000-0000-0000-0000-000000000007', 'Neuroleptic malignant syndrome is a clinical diagnosis of exclusion in the right drug context; it must be distinguished from serotonin syndrome, malignant hyperthermia, and infection.', 3),
('c2000000-0000-0000-0000-000000000008', 'Metronidazole (like other CYP2C9 inhibitors, e.g., some azole antifungals) significantly potentiates warfarin, and INR should be checked closely whenever an interacting antibiotic is started.', 1),
('c2000000-0000-0000-0000-000000000008', 'Management of warfarin over-anticoagulation depends on the INR level and presence/severity of bleeding: minor bleeding with high INR is treated with withholding warfarin plus oral vitamin K; major bleeding requires IV vitamin K and prothrombin complex concentrate.', 2),
('c2000000-0000-0000-0000-000000000008', 'Patients starting any new antibiotic while on warfarin should be counselled about interaction risk and have INR monitored more frequently.', 3),
('c2000000-0000-0000-0000-000000000009', 'CHA2DS2-VASc estimates stroke risk in AF; a score of 2 or more in men (3 or more in women, accounting for the sex category point) generally warrants anticoagulation.', 1),
('c2000000-0000-0000-0000-000000000009', 'DOACs are preferred first-line over warfarin for most patients with non-valvular AF due to convenience, lower intracranial bleeding risk, and no requirement for routine coagulation monitoring.', 2),
('c2000000-0000-0000-0000-000000000009', 'Antiplatelet therapy alone (aspirin, or aspirin plus clopidogrel) is not an effective alternative to anticoagulation for stroke prevention in AF.', 3),
('c2000000-0000-0000-0000-000000000010', 'HIT typically occurs 5-10 days after heparin exposure and is characterised by a significant fall in platelet count with a paradoxically increased risk of thrombosis, not bleeding.', 1),
('c2000000-0000-0000-0000-000000000010', 'All heparin products (unfractionated, LMWH, and heparin flushes/coated catheters) must be stopped once HIT is suspected, and a non-heparin anticoagulant started.', 2),
('c2000000-0000-0000-0000-000000000010', 'Diagnosis is supported by clinical scoring (e.g., the 4Ts score) and confirmed with HIT antibody/functional assays, but treatment should not be delayed pending results if clinical suspicion is high.', 3),
('c2000000-0000-0000-0000-000000000011', 'Major/life-threatening bleeding on warfarin requires immediate reversal with IV vitamin K plus prothrombin complex concentrate (PCC), alongside resuscitation and identification/treatment of the bleeding source.', 1),
('c2000000-0000-0000-0000-000000000011', $x$PCC provides immediate replacement of vitamin K-dependent clotting factors (II, VII, IX, X), while IV vitamin K restores the liver's own factor synthesis over subsequent hours to days.$x$, 2),
('c2000000-0000-0000-0000-000000000011', 'In patients with mechanical heart valves, anticoagulation reversal must be balanced against valve thrombosis risk, and specialist (haematology/cardiology) input should be sought once the immediate bleeding emergency is controlled.', 3),
('c2000000-0000-0000-0000-000000000012', 'Dual antiplatelet therapy duration after drug-eluting stent insertion is typically at least 6-12 months, and premature cessation markedly increases the risk of stent thrombosis.', 1),
('c2000000-0000-0000-0000-000000000012', 'Elective surgery should be deferred where possible until the minimum recommended DAPT duration has passed; if surgery cannot wait, cardiology input is essential to plan safe perioperative management.', 2),
('c2000000-0000-0000-0000-000000000012', 'Stent thrombosis is a life-threatening complication presenting as acute myocardial infarction, distinct from simple in-stent restenosis.', 3),
('c2000000-0000-0000-0000-000000000013', 'Active clinically significant bleeding is an absolute contraindication to pharmacological VTE prophylaxis; mechanical methods should be used instead where feasible.', 1),
('c2000000-0000-0000-0000-000000000013', $x$VTE risk assessment and bleeding risk assessment should both be documented on admission, and the balance reassessed if the patient's clinical status changes (e.g., new bleeding).$x$, 2),
('c2000000-0000-0000-0000-000000000013', $x$Once bleeding has been investigated and controlled, pharmacological VTE prophylaxis should be reconsidered given the patient's ongoing risk factors (reduced mobility, acute illness).$x$, 3),
('c2000000-0000-0000-0000-000000000014', 'Clopidogrel is a prodrug activated by hepatic CYP2C19; drugs that inhibit this enzyme (notably omeprazole and esomeprazole) can reduce its antiplatelet efficacy.', 1),
('c2000000-0000-0000-0000-000000000014', 'Pantoprazole and lansoprazole have weaker CYP2C19 inhibition and are often preferred over omeprazole when gastroprotection is needed alongside clopidogrel.', 2),
('c2000000-0000-0000-0000-000000000014', 'This interaction is a pharmacokinetic (enzyme-mediated) interaction affecting drug activation, distinct from pharmacodynamic interactions that directly add to bleeding risk (e.g., combining antiplatelets with anticoagulants).', 3),
('c2000000-0000-0000-0000-000000000015', 'Simvastatin (and to a lesser extent atorvastatin) are metabolised via CYP3A4; potent CYP3A4 inhibitors (macrolides such as clarithromycin and erythromycin, azole antifungals, protease inhibitors) significantly increase statin levels and myopathy/rhabdomyolysis risk.', 1),
('c2000000-0000-0000-0000-000000000015', 'When a macrolide is needed in a patient on simvastatin/atorvastatin, options include temporarily withholding the statin, using azithromycin (weaker CYP3A4 interaction), or choosing a statin less dependent on CYP3A4 (e.g., rosuvastatin, pravastatin).', 2),
('c2000000-0000-0000-0000-000000000015', 'Dark urine with severe myalgia after starting an interacting drug should raise concern for rhabdomyolysis; CK and renal function should be checked urgently.', 3),
('c2000000-0000-0000-0000-000000000016', 'ACE inhibitors/ARBs and potassium-sparing diuretics (spironolactone, eplerenone, amiloride) both reduce potassium excretion; their combination requires close monitoring of potassium and renal function, especially after initiation or dose changes.', 1),
('c2000000-0000-0000-0000-000000000016', 'Significant hyperkalaemia (typically >6.0 mmol/L) requires urgent action even if the patient is asymptomatic and the ECG is currently normal, because of the risk of sudden life-threatening arrhythmia.', 2),
('c2000000-0000-0000-0000-000000000016', 'Despite this interaction risk, the combination of ACE inhibitor/ARB, beta-blocker, and mineralocorticoid receptor antagonist is standard guideline-directed therapy for heart failure with reduced ejection fraction, requiring planned monitoring rather than avoidance.', 3),
('c2000000-0000-0000-0000-000000000017', 'Trimethoprim and methotrexate both inhibit dihydrofolate reductase; their combination has an additive antifolate effect that can cause severe, sometimes fatal, bone marrow suppression.', 1),
('c2000000-0000-0000-0000-000000000017', 'Co-trimoxazole (trimethoprim-sulfamethoxazole) carries the same risk and should also be avoided in patients on methotrexate.', 2),
('c2000000-0000-0000-0000-000000000017', $x$Prescribers should always check a patient's regular medication list before adding a new drug, particularly antibiotics, given the frequency and severity of interactions with drugs like methotrexate.$x$, 3),
('c2000000-0000-0000-0000-000000000018', $x$Serotonin syndrome results from excess serotonergic activity, classically from combining two or more serotonergic drugs (e.g., SSRI plus tramadol, MAOI, triptan, or St John's Wort).$x$, 1),
('c2000000-0000-0000-0000-000000000018', 'Key clinical features are the triad of neuromuscular abnormalities (tremor, clonus, hyperreflexia, especially in the lower limbs), autonomic instability (fever, sweating, tachycardia), and altered mental status.', 2),
('c2000000-0000-0000-0000-000000000018', 'Management is supportive: stopping all serotonergic drugs, cooling, IV fluids, benzodiazepines for agitation, and cyproheptadine (a serotonin antagonist) in severe cases.', 3),
('c2000000-0000-0000-0000-000000000019', 'Rifampicin is one of the most potent hepatic enzyme inducers used clinically, significantly reducing the effect of many drugs metabolised by CYP450 enzymes, including warfarin, oral contraceptives, and some antiretrovirals.', 1),
('c2000000-0000-0000-0000-000000000019', 'Enzyme induction develops over 1-3 weeks (as new enzyme is synthesised) and resolves gradually after stopping the inducer, in contrast to enzyme inhibition which occurs rapidly.', 2),
('c2000000-0000-0000-0000-000000000019', 'In patients with mechanical heart valves, even brief periods of sub-therapeutic anticoagulation carry a significant risk of valve thrombosis, so INR must be monitored closely and warfarin dose increased proactively when an enzyme inducer is started.', 3),
('c2000000-0000-0000-0000-000000000020', 'Amiodarone (like several other drugs, e.g., verapamil, clarithromycin) inhibits P-glycoprotein-mediated clearance of digoxin, roughly doubling digoxin levels; the digoxin dose is typically halved when amiodarone is co-prescribed.', 1),
('c2000000-0000-0000-0000-000000000020', 'Digoxin toxicity classically presents with GI symptoms (nausea, vomiting, anorexia), visual disturbance (xanthopsia, blurred vision), confusion, and cardiac arrhythmias (including bradycardia and various tachyarrhythmias).', 2),
('c2000000-0000-0000-0000-000000000020', 'Hypokalaemia increases myocardial sensitivity to digoxin and can precipitate toxicity even at therapeutic digoxin levels, so electrolytes should always be checked in suspected digoxin toxicity.', 3),
('c2000000-0000-0000-0000-000000000021', $x$The 'triple whammy' (ACE inhibitor/ARB + diuretic + NSAID) is a well-recognised, common cause of acute kidney injury, particularly in older patients or those with volume depletion.$x$, 1),
('c2000000-0000-0000-0000-000000000021', 'Patients on an ACE inhibitor/ARB with a diuretic should be counselled to avoid over-the-counter NSAIDs and to seek advice if they become unwell with vomiting/diarrhoea (which increases AKI risk further via volume depletion).', 2),
('c2000000-0000-0000-0000-000000000021', 'Management includes stopping the NSAID (and often temporarily the ACE inhibitor and diuretic), rehydration, and monitoring renal function until recovery.', 3),
('c2000000-0000-0000-0000-000000000022', 'Phenytoin exhibits dose-dependent (saturable) kinetics: at low doses it follows first-order kinetics, but once hepatic metabolism is saturated near the therapeutic range, it switches to zero-order kinetics.', 1),
('c2000000-0000-0000-0000-000000000022', 'Because of this, phenytoin dose increases should be made in small increments with careful monitoring of levels and clinical toxicity, especially once levels are within or near the therapeutic range.', 2),
('c2000000-0000-0000-0000-000000000022', 'Signs of phenytoin toxicity include nystagmus, ataxia, diplopia, slurred speech, and, at higher levels, confusion and decreased consciousness.', 3),
('c2000000-0000-0000-0000-000000000023', 'For drugs with a long half-life, steady state with maintenance dosing alone takes approximately 4-5 half-lives to be reached; a loading dose strategy is used when a rapid therapeutic effect is needed.', 1),
('c2000000-0000-0000-0000-000000000023', 'After a loading dose achieves the target concentration, the maintenance dose is calculated to replace only what is eliminated between doses, keeping the concentration within the therapeutic range.', 2),
('c2000000-0000-0000-0000-000000000023', 'Drugs with a narrow therapeutic index and long half-life (e.g., digoxin, amiodarone) commonly use loading dose regimens in urgent clinical situations.', 3),
('c2000000-0000-0000-0000-000000000024', 'Rifampicin (and rifabutin) are potent enzyme inducers that reduce the efficacy of combined and progestogen-only hormonal contraception; additional contraceptive precautions are needed during treatment and for a period afterwards.', 1),
('c2000000-0000-0000-0000-000000000024', 'Enzyme induction takes days to weeks to develop fully (as new enzyme protein must be synthesised) and persists for a similar period after the inducing drug is stopped.', 2),
('c2000000-0000-0000-0000-000000000024', 'Non-hormonal contraceptive methods (e.g., copper intrauterine device) or barrier methods are unaffected by enzyme induction and are appropriate alternatives during enzyme-inducing drug courses.', 3),
('c2000000-0000-0000-0000-000000000025', 'First-pass metabolism refers to hepatic (and sometimes gut wall) metabolism of a drug after oral absorption and before it reaches the systemic circulation, which can markedly reduce bioavailability for some drugs.', 1),
('c2000000-0000-0000-0000-000000000025', 'Routes that avoid first-pass metabolism include sublingual, buccal, rectal (partially), transdermal, inhaled, and parenteral administration.', 2),
('c2000000-0000-0000-0000-000000000025', 'Drugs with high first-pass metabolism (e.g., GTN, morphine to a lesser extent) often require much higher oral doses than parenteral/sublingual doses to achieve the same systemic effect.', 3),
('c2000000-0000-0000-0000-000000000026', 'With regular fixed-dose, fixed-interval dosing and no loading dose, plasma concentration approaches steady state after approximately 4-5 half-lives.', 1),
('c2000000-0000-0000-0000-000000000026', $x$The time to reach steady state depends only on the drug's half-life, not on the size of the maintenance dose (the dose determines the level at steady state, not how quickly it is reached).$x$, 2),
('c2000000-0000-0000-0000-000000000026', 'A loading dose can be used to achieve a therapeutic concentration more rapidly than waiting for steady state with maintenance dosing alone.', 3),
('c2000000-0000-0000-0000-000000000027', $x$Only the unbound (free) fraction of a highly protein-bound drug is pharmacologically active; conditions causing hypoalbuminaemia (cirrhosis, nephrotic syndrome, malnutrition) can increase the free fraction and cause toxicity despite a 'normal' total drug level.$x$, 1),
('c2000000-0000-0000-0000-000000000027', 'Phenytoin is approximately 90% protein-bound; in states of hypoalbuminaemia, free phenytoin levels (rather than total levels) should be used to guide dosing where available.', 2),
('c2000000-0000-0000-0000-000000000027', 'Other highly protein-bound drugs affected by this phenomenon include valproate and some benzodiazepines.', 3),
('c2000000-0000-0000-0000-000000000028', 'Codeine and tramadol are prodrugs requiring CYP2D6-mediated conversion to their active metabolites (morphine and O-desmethyltramadol respectively); CYP2D6 poor metabolisers get little analgesic benefit from these drugs.', 1),
('c2000000-0000-0000-0000-000000000028', 'CYP2D6 ultra-rapid metabolisers are at increased risk of opioid toxicity from codeine (notably reported in some breastfeeding mothers causing neonatal morphine toxicity via breast milk), the opposite problem to poor metabolisers.', 2),
('c2000000-0000-0000-0000-000000000028', $x$Because morphine does not require this metabolic activation step, it remains a reliable analgesic choice regardless of a patient's CYP2D6 metaboliser status.$x$, 3),
('c2000000-0000-0000-0000-000000000029', 'In acute single-ingestion paracetamol overdose, treatment decisions are based on the plasma paracetamol concentration plotted against time since ingestion on the treatment nomogram (from 4 hours post-ingestion).', 1),
('c2000000-0000-0000-0000-000000000029', 'N-acetylcysteine works by replenishing hepatic glutathione, which detoxifies the toxic metabolite NAPQI; it is most effective when started early (ideally within 8 hours of ingestion) but is still given later if indicated.', 2),
('c2000000-0000-0000-0000-000000000029', 'Activated charcoal may be considered if the patient presents within around 1 hour of a large ingestion, but is not a substitute for N-acetylcysteine when the level indicates treatment is needed.', 3),
('c2000000-0000-0000-0000-000000000030', 'Salicylate poisoning classically causes a mixed acid-base picture: early respiratory alkalosis (direct respiratory centre stimulation) combined with a raised anion gap metabolic acidosis (organic acid accumulation, uncoupled oxidative phosphorylation).', 1),
('c2000000-0000-0000-0000-000000000030', 'Key management includes IV fluids, urinary alkalinisation with IV sodium bicarbonate (which enhances renal elimination of salicylate by ion trapping), and correction of hypokalaemia (needed for alkalinisation to be effective).', 2),
('c2000000-0000-0000-0000-000000000030', 'Haemodialysis is used for severe salicylate poisoning (e.g., very high levels, severe acidosis, renal failure, or pulmonary oedema).', 3),
('c2000000-0000-0000-0000-000000000031', 'The opioid toxidrome classically includes pinpoint (miotic) pupils, respiratory depression, and reduced level of consciousness.', 1),
('c2000000-0000-0000-0000-000000000031', 'Naloxone has a shorter half-life than many opioids (especially long-acting or slow-release preparations), so patients may need repeated doses or an infusion, and require ongoing monitoring for re-sedation after apparent reversal.', 2),
('c2000000-0000-0000-0000-000000000031', 'Airway, breathing, and oxygenation support take priority alongside naloxone administration in any patient with significant respiratory compromise.', 3),
('c2000000-0000-0000-0000-000000000032', 'Flumazenil reverses benzodiazepine sedation but can precipitate seizures, particularly in chronic benzodiazepine users (acute withdrawal) and in mixed overdoses with pro-convulsant drugs such as tricyclic antidepressants.', 1),
('c2000000-0000-0000-0000-000000000032', 'Most benzodiazepine overdoses are managed with supportive care alone (airway, breathing, monitoring), since isolated benzodiazepine toxicity is rarely life-threatening in adults with an intact airway.', 2),
('c2000000-0000-0000-0000-000000000032', 'Flumazenil use is generally reserved for specific situations such as reversing iatrogenic over-sedation during procedures, under close monitoring, rather than routine use in self-poisoning.', 3),
('c2000000-0000-0000-0000-000000000033', 'QRS widening (>100 ms) and rightward axis deviation on ECG in tricyclic antidepressant overdose reflect sodium channel blockade and predict risk of seizures and ventricular arrhythmia.', 1),
('c2000000-0000-0000-0000-000000000033', 'IV sodium bicarbonate is the first-line treatment for cardiotoxicity in TCA overdose, aiming to narrow the QRS complex and stabilise cardiac conduction.', 2),
('c2000000-0000-0000-0000-000000000033', 'Class Ia/Ic antiarrhythmics should be avoided in TCA overdose as they compound sodium channel blockade and worsen cardiotoxicity.', 3),
('c2000000-0000-0000-0000-000000000034', 'Serum iron concentration (appropriately timed) is used to assess severity of iron overdose and the need for chelation with desferrioxamine, alongside clinical features (GI symptoms, lethargy, acidosis, shock).', 1),
('c2000000-0000-0000-0000-000000000034', 'Iron overdose has a classically described biphasic or multi-phase course: early GI symptoms, an apparent improvement, then potential later deterioration with metabolic acidosis, shock, and hepatic failure if severe.', 2),
('c2000000-0000-0000-0000-000000000034', 'Desferrioxamine is the chelating agent used in significant iron toxicity, binding free iron to form ferrioxamine, which is renally excreted.', 3),
('c2000000-0000-0000-0000-000000000035', 'Severe beta-blocker overdose causes bradycardia, hypotension, and can cause hypoglycaemia and seizures (especially with propranolol, which also has membrane-stabilising/sodium-channel blocking effects at high doses, similar to tricyclics).', 1),
('c2000000-0000-0000-0000-000000000035', 'IV glucagon is a specific treatment for beta-blocker-induced cardiotoxicity refractory to atropine, acting via a cAMP-mediated pathway independent of the beta-receptor.', 2),
('c2000000-0000-0000-0000-000000000035', 'High-dose insulin-euglycaemia therapy is used in refractory beta-blocker (and calcium channel blocker) overdose when glucagon and other measures are insufficient.', 3),
('c2000000-0000-0000-0000-000000000036', 'Metformin accumulation in significant renal impairment (particularly AKI, or eGFR <30, and used cautiously between 30-45) increases the risk of lactic acidosis; it should be withheld during acute illness that risks or causes AKI.', 1),
('c2000000-0000-0000-0000-000000000036', 'Sick day rules for metformin (and other renally cleared or nephrotoxic drugs) advise temporarily stopping the drug during acute illness with vomiting, diarrhoea, fever, or dehydration.', 2),
('c2000000-0000-0000-0000-000000000036', 'Metformin can typically be restarted once renal function has returned to baseline and the acute illness has resolved.', 3),
('c2000000-0000-0000-0000-000000000037', 'NSAIDs inhibit prostaglandin synthesis, reducing compensatory afferent arteriolar vasodilation; in patients with reduced renal reserve (CKD, volume depletion, heart failure, or on ACE inhibitors/diuretics), this can precipitate significant deterioration in renal function.', 1),
('c2000000-0000-0000-0000-000000000037', 'NSAIDs should generally be avoided or used with extreme caution and close monitoring in patients with an eGFR below around 30-60 mL/min/1.73m2, depending on severity and other risk factors.', 2),
('c2000000-0000-0000-0000-000000000037', 'Paracetamol is generally the preferred first-line analgesic in CKD, as it does not share this nephrotoxic mechanism, though other options should be considered if pain control remains inadequate.', 3),
('c2000000-0000-0000-0000-000000000038', 'Gentamicin (and other aminoglycosides) are renally excreted and both nephrotoxic and ototoxic; dosing regimens and intervals must be adjusted according to renal function, with levels monitored to avoid accumulation.', 1),
('c2000000-0000-0000-0000-000000000038', 'Nephrotoxicity from aminoglycosides can create a vicious cycle, as worsening renal function further reduces drug clearance, increasing toxicity risk further.', 2),
('c2000000-0000-0000-0000-000000000038', 'Local guidelines/pharmacy input should always be used for aminoglycoside dosing, particularly in renal impairment, obesity, or critical illness, where standard weight-based dosing may be inappropriate.', 3),
('c2000000-0000-0000-0000-000000000039', $x$Morphine's active metabolites (notably morphine-6-glucuronide) are renally excreted and accumulate in renal impairment, causing opioid toxicity even at doses that would be safe with normal renal function.$x$, 1),
('c2000000-0000-0000-0000-000000000039', 'In significant renal impairment, opioids such as oxycodone (with caution and dose reduction) or fentanyl/alfentanil (which have less dependence on renal clearance of active metabolites) are generally preferred over morphine.', 2),
('c2000000-0000-0000-0000-000000000039', 'Signs of opioid toxicity include sedation, pinpoint pupils, and respiratory depression; management includes reducing/stopping the opioid and considering naloxone if severe.', 3),
('c2000000-0000-0000-0000-000000000040', 'Digoxin is predominantly renally excreted; maintenance doses must be reduced in renal impairment, and levels monitored, to avoid toxic accumulation.', 1),
('c2000000-0000-0000-0000-000000000040', 'Digoxin toxicity presents with GI symptoms (nausea, vomiting, anorexia), visual disturbance (xanthopsia), confusion, and cardiac arrhythmias including bradycardia.', 2),
('c2000000-0000-0000-0000-000000000040', 'Electrolyte disturbances, particularly hypokalaemia (and renal impairment often coexists with electrolyte disturbance), increase the risk of digoxin toxicity even at lower drug levels.', 3),
('c2000000-0000-0000-0000-000000000041', 'Sedating drugs (opioids, benzodiazepines) are recognised precipitants of hepatic encephalopathy and should be used cautiously, at reduced doses, or avoided in patients with significant liver disease.', 1),
('c2000000-0000-0000-0000-000000000041', 'Reduced hepatic metabolism in liver impairment can lead to accumulation of opioids and their metabolites, prolonging and intensifying sedative and respiratory depressant effects.', 2),
('c2000000-0000-0000-0000-000000000041', 'When analgesia is required in advanced liver disease, doses should be reduced, non-sedating adjuncts considered where appropriate, and the patient closely monitored for worsening conscious level.', 3),
('c2000000-0000-0000-0000-000000000042', 'ACE inhibitors/ARBs can cause a rise in creatinine and potassium, particularly in patients with pre-existing CKD, renovascular disease, or those on other drugs affecting potassium/renal perfusion; renal function and potassium should be checked before starting and within 1-2 weeks after initiation or dose increase.', 1),
('c2000000-0000-0000-0000-000000000042', 'A modest rise in creatinine (generally up to around 20-30%) after starting an ACE inhibitor/ARB can be an expected haemodynamic effect, but a larger rise or significant hyperkalaemia warrants dose reduction or stopping the drug and further investigation (e.g., for renal artery stenosis).', 2),
('c2000000-0000-0000-0000-000000000042', 'Despite these monitoring requirements, ACE inhibitors/ARBs remain an important, often renoprotective, treatment in appropriate CKD patients and should not be avoided purely because of CKD.', 3),
('c2000000-0000-0000-0000-000000000043', $x$Insulin is a high-risk medication, and the abbreviation 'U' (for units) is specifically prohibited in prescribing because it can be misread as a zero or the numeral '10', leading to potentially fatal tenfold overdoses.$x$, 1),
('c2000000-0000-0000-0000-000000000043', $x$'Units' should always be written in full when prescribing insulin (and other medications dosed in units, such as heparin).$x$, 2),
('c2000000-0000-0000-0000-000000000043', 'Independent double-checking of insulin doses by two members of staff before administration is an additional recognised safety measure for this high-risk drug.', 3),
('c2000000-0000-0000-0000-000000000044', 'Concentrated potassium chloride must never be given as an undiluted rapid intravenous bolus; it must always be diluted appropriately and infused at a controlled rate, following local protocols.', 1),
('c2000000-0000-0000-0000-000000000044', 'Concentrated potassium ampoules are classified as a high-risk medication in many healthcare systems, often stored separately with restricted access to prevent inadvertent direct administration.', 2),
('c2000000-0000-0000-0000-000000000044', 'Rapid correction of hypokalaemia should still be done cautiously with cardiac monitoring for higher infusion rates, as both hypokalaemia and iatrogenic hyperkalaemia can cause life-threatening arrhythmias.', 3),
('c2000000-0000-0000-0000-000000000045', $x$Amlodipine and amiloride are a well-recognised look-alike/sound-alike (LASA) drug pair that can be confused during prescribing or transcription, potentially causing harm from the unintended drug's effects.$x$, 1),
('c2000000-0000-0000-0000-000000000045', $x$Medication reconciliation on admission should always verify each drug's name, dose, and indication against a reliable source (e.g., the patient, their own medication list, or GP records), rather than relying on transcription alone.$x$, 2),
('c2000000-0000-0000-0000-000000000045', 'When multiple drugs affecting potassium (potassium-sparing diuretics, ACE inhibitors/ARBs) are combined, even inadvertently, the risk of significant hyperkalaemia is substantially increased.', 3),
('c2000000-0000-0000-0000-000000000046', 'A documented severe drug allergy must be actively checked before prescribing any new medication; failure to do so is a common and serious preventable prescribing error.', 1),
('c2000000-0000-0000-0000-000000000046', 'Co-amoxiclav, and other penicillin-class or related beta-lactam antibiotics, must be avoided in patients with a history of significant penicillin allergy/anaphylaxis, with an alternative antibiotic class chosen instead.', 2),
('c2000000-0000-0000-0000-000000000046', $x$Systems such as electronic prescribing allergy alerts, allergy wristbands, and clear allergy documentation on drug charts support but do not replace the prescriber's responsibility to actively check allergy status.$x$, 3),
('c2000000-0000-0000-0000-000000000047', $x$Oral methotrexate for conditions such as rheumatoid arthritis and psoriasis is dosed once weekly; mistaking this for a daily dose is a recognised, potentially fatal 'never event'-type prescribing error.$x$, 1),
('c2000000-0000-0000-0000-000000000047', 'Methotrexate is designated a high-risk medication requiring specific safeguards: clear documentation of the weekly dosing day, patient-held treatment booklets/alert cards, and pharmacist verification at prescribing, dispensing, and transitions of care (e.g., discharge summaries).', 2),
('c2000000-0000-0000-0000-000000000047', 'Methotrexate toxicity from dosing errors presents with mucositis, GI symptoms, and bone marrow suppression (pancytopenia), and can be fatal without prompt recognition and treatment (including folinic acid rescue).', 3),
('c2000000-0000-0000-0000-000000000048', $x$Vincristine (and other vinca alkaloids) must only ever be given intravenously; intrathecal administration is a recognised 'never event' that is almost always fatal due to irreversible ascending encephalomyelopathy.$x$, 1),
('c2000000-0000-0000-0000-000000000048', 'National safety guidance mandates strict separation of intrathecal and intravenous chemotherapy administration in time, location, equipment, and staff, with only specifically trained and authorised staff permitted to prepare, prescribe, or administer intrathecal chemotherapy.', 2),
('c2000000-0000-0000-0000-000000000048', 'Any near-miss or actual error involving intrathecal chemotherapy should be treated as a serious patient safety incident requiring immediate action and full incident reporting/review, given the potential severity.', 3),
('c2000000-0000-0000-0000-000000000049', 'Long-term corticosteroid therapy suppresses the hypothalamic-pituitary-adrenal axis; abrupt cessation can precipitate a life-threatening adrenal crisis and must be avoided through gradual tapering.', 1),
('c2000000-0000-0000-0000-000000000049', 'All patients on long-term corticosteroids should carry a steroid card, and their regular steroid dose must be clearly documented and continued (not omitted) at every transition of care, including hospital discharge.', 2),
('c2000000-0000-0000-0000-000000000049', 'Adrenal crisis presents with hypotension, vomiting, abdominal pain, hypoglycaemia, and lethargy/collapse, and is treated as a medical emergency with immediate IV hydrocortisone and fluid resuscitation.', 3),
('c2000000-0000-0000-0000-000000000050', 'Confusing milligram and microgram doses is a well-recognised, high-severity prescribing error, particularly dangerous with potent drugs dosed in micrograms (e.g., fentanyl, digoxin in some contexts).', 1),
('c2000000-0000-0000-0000-000000000050', 'Units should always be written clearly and unambiguously (avoiding easily confused abbreviations), and unfamiliar or high-risk drug doses should be checked against a reliable reference source before prescribing.', 2),
('c2000000-0000-0000-0000-000000000050', $x$Systems such as electronic prescribing with dose-range checking/alerts, and independent double-checking for high-risk drugs, provide additional safeguards but do not remove the prescriber's primary responsibility for an accurate prescription.$x$, 3);
